QT_ISI(6,{"641":["(Allah tidak menyukai perkataan buruk yang diucapkan secara terus terang) dari siapa pun juga, artinya Dia pastilah akan memberinya hukuman (kecuali dari orang yang dianiaya) sehingga apabila dia mengucapkannya secara terus terang misalnya tentang keaniayaan yang dideritanya sehingga ia mendoakan si pelakunya, maka tidaklah dia akan menerima hukuman dari Allah. (Dan Allah Maha Mendengar) apa-apa yang diucapkan (lagi Maha Mengetahui) apa-apa yang diperbuat.",[["۞ لَّا","(Does) not"],["يُحِبُّ","love"],["ٱللَّهُ","Allah"],["ٱلْجَهْرَ","the public mention"],["بِٱلسُّوٓءِ","of [the] evil"],["مِنَ","[of]"],["ٱلْقَوْلِ","[the] words"],["إِلَّا","except"],["مَن","(by the one) who"],["ظُلِمَ ۚ","has been wronged"],["وَكَانَ","And is"],["ٱللَّهُ","Allah"],["سَمِيعًا","All-Hearing"],["عَلِيمًا","All-Knowing"]]],"642":["(Jika kamu melahirkan) atau memperlihatkan (suatu kebaikan) di antara perbuatan-perbuatan baik (atau menyembunyikannya) artinya melakukannya secara sembunyi-sembunyi (atau memaafkan sesuatu kesalahan) atau keaniayaan orang lain (maka sesungguhnya Allah Maha Pemaaf lagi Maha Kuasa).",[["إِن","If"],["تُبْدُوا۟","you disclose"],["خَيْرًا","a good"],["أَوْ","or"],["تُخْفُوهُ","you conceal it"],["أَوْ","or"],["تَعْفُوا۟","pardon"],["عَن","[of]"],["سُوٓءٍۢ","an evil"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["كَانَ","is"],["عَفُوًّۭا","Oft-Pardoning"],["قَدِيرًا","All-Powerful"]]],"643":["(Sesungguhnya orang-orang yang kafir kepada Allah dan rasul-rasul-Nya dan bermaksud akan membeda-bedakan di antara Allah dengan rasul-rasul-Nya) yakni dengan beriman kepada-Nya serta kafir terhadap mereka (serta mengatakan, \"Kami beriman kepada sebagian) di antara rasul-rasul itu (dan kami kafir terhadap yang lain\") dari mereka (serta bermaksud hendak mengambil di antara demikian) maksudnya di antara kufur dan iman (jalan) yang akan mereka tempuh.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["يَكْفُرُونَ","disbelieve"],["بِٱللَّهِ","in Allah"],["وَرُسُلِهِۦ","and His Messengers"],["وَيُرِيدُونَ","and they wish"],["أَن","that"],["يُفَرِّقُوا۟","they differentiate"],["بَيْنَ","between"],["ٱللَّهِ","Allah"],["وَرُسُلِهِۦ","and His Messengers"],["وَيَقُولُونَ","and they say"],["نُؤْمِنُ","We believe"],["بِبَعْضٍۢ","in some"],["وَنَكْفُرُ","and we disbelieve"],["بِبَعْضٍۢ","in others"],["وَيُرِيدُونَ","And they wish"],["أَن","that"],["يَتَّخِذُوا۟","they take"],["بَيْنَ","between"],["ذَٰلِكَ","that"],["سَبِيلًا","a way"]]],"644":["(Merekalah orang-orang yang kafir sebenar-benarnya) haqqan adalah mashdar yang memperkuat isi kalimat sebelumnya (dan telah Kami sediakan bagi orang-orang yang kafir itu siksaan yang menghinakan) artinya azab neraka.",[["أُو۟لَـٰٓئِكَ","Those "],["هُمُ","they"],["ٱلْكَـٰفِرُونَ","(are) the disbelievers"],["حَقًّۭا ۚ","truly"],["وَأَعْتَدْنَا","And We have prepared"],["لِلْكَـٰفِرِينَ","for the disbelievers"],["عَذَابًۭا","a punishment"],["مُّهِينًۭا","humiliating"]]],"645":["(Orang-orang yang beriman kepada Allah dan para rasul-Nya) artinya semua mereka (dan tidak membeda-bedakan seorang pun di antara mereka kelak Allah akan memberikan kepada mereka) dengan memakai nun atau ya (pahala mereka) artinya pahala amal perbuatan mereka (dan Allah Maha Pengampun) bagi kekasih-kekasih-Nya (lagi Maha Penyayang) kepada ahli taat-Nya.",[["وَٱلَّذِينَ","And those who"],["ءَامَنُوا۟","believe"],["بِٱللَّهِ","in Allah"],["وَرُسُلِهِۦ","and His Messengers"],["وَلَمْ","and not"],["يُفَرِّقُوا۟","they differentiate"],["بَيْنَ","between"],["أَحَدٍۢ","(any) one"],["مِّنْهُمْ","of them"],["أُو۟لَـٰٓئِكَ","those "],["سَوْفَ","soon"],["يُؤْتِيهِمْ","He will give them"],["أُجُورَهُمْ ۗ","their reward"],["وَكَانَ","And is"],["ٱللَّهُ","Allah"],["غَفُورًۭا","Oft-Forgiving"],["رَّحِيمًۭا","Most Merciful"]]],"646":["(Ahli Kitab meminta kepadamu) hai Muhammad; maksudnya orang-orang Yahudi (agar kamu menurunkan kepada mereka sebuah kitab dari langit) maksudnya sekaligus seperti pernah diturunkan-Nya kepada Musa guna mempersulit permintaan itu. Dan sekiranya menurut kamu itu berat (maka sesungguhnya mereka telah pernah meminta) maksudnya nenek moyang mereka (kepada Musa yang lebih besar dari itu, kata mereka, \"Perlihatkanlah Allah kepada kami dengan jelas.\") atau nyata. (Maka mereka disambar oleh petir) artinya maut sebagai hukuman bagi mereka (disebabkan keaniayaan mereka) yakni meminta barang yang sulit. (Kemudian mereka mengambil anak sapi) sebagai tuhan (setelah datang kepada mereka bukti-bukti yang nyata) artinya mukjizat-mukjizat atas kekuasaan Allah (maka Kami maafkan mereka dari hal yang demikian) dan tidak Kami basmi mereka secara tuntas (dan telah Kami berikan kepada Musa kekuasaan yang nyata) artinya keunggulan yang menakjubkan bagi mereka hingga sewaktu mereka disuruh membunuh diri mereka guna bertobat mereka pun menurutinya dengan patuh.",[["يَسْـَٔلُكَ","Ask you"],["أَهْلُ","(the) People"],["ٱلْكِتَـٰبِ","(of) the Book"],["أَن","that"],["تُنَزِّلَ","you bring down"],["عَلَيْهِمْ","to them"],["كِتَـٰبًۭا","a book"],["مِّنَ","from"],["ٱلسَّمَآءِ ۚ","the heaven"],["فَقَدْ","Then indeed"],["سَأَلُوا۟","they (had) asked"],["مُوسَىٰٓ","Musa"],["أَكْبَرَ","greater"],["مِن","than"],["ذَٰلِكَ","that"],["فَقَالُوٓا۟","for they said"],["أَرِنَا","Show us"],["ٱللَّهَ","Allah"],["جَهْرَةًۭ","manifestly"],["فَأَخَذَتْهُمُ","so struck them"],["ٱلصَّـٰعِقَةُ","the thunderbolt"],["بِظُلْمِهِمْ ۚ","for their wrongdoing"],["ثُمَّ","Then"],["ٱتَّخَذُوا۟","they took"],["ٱلْعِجْلَ","the calf (for worship)"],["مِنۢ","from"],["بَعْدِ","after"],["مَا","[what]"],["جَآءَتْهُمُ","came to them"],["ٱلْبَيِّنَـٰتُ","the clear proofs"],["فَعَفَوْنَا","then We forgave them"],["عَن","for"],["ذَٰلِكَ ۚ","that"],["وَءَاتَيْنَا","And We gave"],["مُوسَىٰ","Musa"],["سُلْطَـٰنًۭا","an authority"],["مُّبِينًۭا","clear"]]],"647":["(Dan Kami angkat ke atas kepada mereka Thur) nama sebuah bukit (disebabkan perjanjian dengan mereka) maksudnya hendak mengadakan perjanjian agar mereka takut dan bersedia menerimanya (dan kata Kami kepada mereka) sementara bukit itu dinaungkan kepada mereka (\"Masukilah pintu gerbang itu) maksudnya pintu gerbang kampung atau negeri (sambil bersujud\") yang menunjukkan ketundukkan (dan Kami wahyukan kepada mereka, \"Janganlah kamu melanggar perintah) menurut suatu qiraat dibaca ta`adduu dengan diidgamkan ta aslinya pada dal yang menjadi ta`taduu; artinya melanggar perintah (pada hari Sabtu\") dengan menangkap ikan padanya (dan Kami telah menerima perjanjian erat dari mereka) mengenai hal itu tetapi mereka melanggarnya.",[["وَرَفَعْنَا","And We raised"],["فَوْقَهُمُ","over them"],["ٱلطُّورَ","the mount"],["بِمِيثَـٰقِهِمْ","for their covenant"],["وَقُلْنَا","and We said"],["لَهُمُ","to them"],["ٱدْخُلُوا۟","Enter"],["ٱلْبَابَ","the gate"],["سُجَّدًۭا","prostrating"],["وَقُلْنَا","And We said"],["لَهُمْ","to them"],["لَا","(Do) not"],["تَعْدُوا۟","transgress"],["فِى","in"],["ٱلسَّبْتِ","the Sabbath"],["وَأَخَذْنَا","And We took"],["مِنْهُم","from them"],["مِّيثَـٰقًا","a covenant"],["غَلِيظًۭا","solemn"]]],"648":["(Maka disebabkan mereka melanggar) ma merupakan tambahan; ba sababiyah berkaitan dengan yang dibuang, yang maksudnya: Kami kutuk mereka disebabkan mereka melanggar (perjanjian mereka dan karena kekafiran mereka terhadap ayat-ayat Allah dan pembunuhan yang mereka lakukan kepada nabi-nabi tanpa alasan yang benar dan kata mereka) kepada Nabi saw. (\"Hati kami tertutup\") tak dapat mendengar apa yang kamu katakan (bahkan Allah telah mengunci hati mereka itu disebabkan kekafiran mereka) hingga tak dapat mendengarkan nasihat dan pelajaran (oleh karena itu mereka tidak beriman kecuali sebagian kecil) dari mereka seperti Abdullah bin Salam dan kawan-kawannya.",[["فَبِمَا","Then because of"],["نَقْضِهِم","their breaking"],["مِّيثَـٰقَهُمْ","(of) their covenant"],["وَكُفْرِهِم","and their disbelief"],["بِـَٔايَـٰتِ","in (the) Signs"],["ٱللَّهِ","(of) Allah"],["وَقَتْلِهِمُ","and their killing"],["ٱلْأَنۢبِيَآءَ","(of) the Prophets"],["بِغَيْرِ","without"],["حَقٍّۢ","any right"],["وَقَوْلِهِمْ","and their saying"],["قُلُوبُنَا","Our hearts"],["غُلْفٌۢ ۚ","(are) wrapped"],["بَلْ","Nay"],["طَبَعَ","(has) set a seal"],["ٱللَّهُ","Allah"],["عَلَيْهَا","on their (hearts)"],["بِكُفْرِهِمْ","for their disbelief"],["فَلَا","so not"],["يُؤْمِنُونَ","they believe"],["إِلَّا","except"],["قَلِيلًۭا","a few"]]],"649":["(Dan karena kekafiran mereka) buat kedua kalinya yakni terhadap Isa, dan ba diulang-ulang menyebutkannya untuk memisah di antaranya dengan tempat mengathafkannya (dan tuduhan mereka terhadap Maryam berupa kedustaan besar) di mana mereka menuduhnya berbuat zina.",[["وَبِكُفْرِهِمْ","And for their disbelief"],["وَقَوْلِهِمْ","and their saying"],["عَلَىٰ","against"],["مَرْيَمَ","Maryam"],["بُهْتَـٰنًا","a slander"],["عَظِيمًۭا","great"]]],"650":["(Serta karena ucapan mereka) dengan membanggakan diri (\"Sesungguhnya kami telah membunuh Almasih Isa putra Maryam utusan Allah\") yakni menurut dugaan dan pengakuan mereka. Artinya disebabkan semua itu Kami siksa mereka. Dan Allah berfirman menolak pengakuan mereka telah membunuhnya itu (padahal mereka tidak membunuhnya dan tidak pula menyalibnya tetapi diserupakan bagi mereka dengan Isa) maksudnya yang mereka bunuh dan mereka salib itu ialah sahabat mereka sendiri yang diserupakan Allah dengan Isa hingga mereka kira Nabi Isa sendiri. (Sesungguhnya orang-orang yang berselisih paham padanya) maksudnya pada Isa (sesungguhnya dalam keragu-raguan terhadapnya) maksudnya terhadap pembunuhan itu. Agar terlihat orang yang dibunuh itu, sebagian mereka berkata, \"Mukanya seperti muka Isa, tetapi tubuhnya lain, jadi sebenarnya bukan dia!\" Dan kata sebagian pula, \"Memang dia itu Isa!\" (mereka tidak mempunyai terhadapnya) maksudnya pembunuhan itu (keyakinan kecuali mengikuti persangkaan belaka) disebut sebagai istitsna munqathi'; artinya mereka hanya mengikuti dugaan-dugaan hasil khayal atau lamunan belaka (mereka tidak yakin telah membunuh Isa) menjadi hal yang menyangkal pembunuhan Isa itu.",[["وَقَوْلِهِمْ","And for their saying"],["إِنَّا","Indeed, we"],["قَتَلْنَا","killed"],["ٱلْمَسِيحَ","the Messiah"],["عِيسَى","Isa"],["ٱبْنَ","son"],["مَرْيَمَ","(of) Maryam"],["رَسُولَ","(the) Messenger"],["ٱللَّهِ","(of) Allah"],["وَمَا","And not"],["قَتَلُوهُ","they killed him"],["وَمَا","and not"],["صَلَبُوهُ","they crucified him"],["وَلَـٰكِن","but"],["شُبِّهَ","it was made to appear (so)"],["لَهُمْ ۚ","to them"],["وَإِنَّ","And indeed"],["ٱلَّذِينَ","those who"],["ٱخْتَلَفُوا۟","differ"],["فِيهِ","in it"],["لَفِى","(are) surely in"],["شَكٍّۢ","doubt"],["مِّنْهُ ۚ","about it"],["مَا","Not"],["لَهُم","for them"],["بِهِۦ","about it"],["مِنْ","[of]"],["عِلْمٍ","(any) knowledge"],["إِلَّا","except"],["ٱتِّبَاعَ","(the) following"],["ٱلظَّنِّ ۚ","(of) assumption"],["وَمَا","And not"],["قَتَلُوهُ","they killed him"],["يَقِينًۢا","certainly"]]],"651":["(Tetapi Allah telah mengangkatnya kepada-Nya dan Allah Maha Tangguh) dalam kerajaan-Nya (lagi Maha Bijaksana) dalam perbuatan-Nya.",[["بَل","Nay"],["رَّفَعَهُ","he was raised"],["ٱللَّهُ","(by) Allah"],["إِلَيْهِ ۚ","towards Him"],["وَكَانَ","And is"],["ٱللَّهُ","Allah"],["عَزِيزًا","All-Mighty"],["حَكِيمًۭا","All-Wise"]]],"652":["(Dan tidak ada di antara Ahli Kitab) seorang pun juga (kecuali akan beriman kepadanya) yakin kepada Isa (sebelum meninggalnya) artinya sebelum ahli Kitab itu meninggal di waktu ia melihat malaikat maut, tetapi keimanannya itu sudah tidak berguna lagi. Atau sebelum wafatnya Isa, yakni ketika dia turun dekat datangnya hari kiamat sebagaimana tercantum dalam sebuah hadis (Dan pada hari kiamat itu, ia) yakni Isa (akan menjadi saksi terhadap mereka) mengenai apa yang mereka lakukan sewaktu ia diutus kepada mereka dahulu.",[["وَإِن","And (there is) not"],["مِّنْ","from"],["أَهْلِ","(the) People"],["ٱلْكِتَـٰبِ","(of) the Book"],["إِلَّا","but"],["لَيُؤْمِنَنَّ","surely he believes"],["بِهِۦ","in him"],["قَبْلَ","before"],["مَوْتِهِۦ ۖ","his death"],["وَيَوْمَ","And (on the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["يَكُونُ","he will be"],["عَلَيْهِمْ","against them"],["شَهِيدًۭا","a witness"]]],"653":["(Maka karena keaniayaan) artinya disebabkan keaniayaan (dari orang-orang Yahudi Kami haramkan atas mereka makanan yang baik-baik yang dihalalkan bagi mereka dulu) yakni yang tersebut dalam firman-Nya, \"Kami haramkan setiap yang berkuku...\" sampai akhir ayat (juga karena mereka menghalangi) manusia (dari jalan Allah) maksudnya agama-Nya (banyak).",[["فَبِظُلْمٍۢ","Then for (the) wrongdoing"],["مِّنَ","of"],["ٱلَّذِينَ","those who"],["هَادُوا۟","were Jews"],["حَرَّمْنَا","We made unlawful"],["عَلَيْهِمْ","for them"],["طَيِّبَـٰتٍ","good things"],["أُحِلَّتْ","which had been lawful"],["لَهُمْ","for them"],["وَبِصَدِّهِمْ","and for their hindering"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah "],["كَثِيرًۭا","many"]]],"654":["(Dan karena memakan riba padahal telah dilarang daripadanya) dalam Taurat (dan memakan harta orang dengan jalan batil) dengan memberi suap dalam pengadilan (dan telah Kami sediakan untuk orang-orang kafir itu siksa yang pedih) atau menyakitkan.",[["وَأَخْذِهِمُ","And for their taking"],["ٱلرِّبَوٰا۟","(of) [the] usury"],["وَقَدْ","while certainly"],["نُهُوا۟","they were forbidden"],["عَنْهُ","from it"],["وَأَكْلِهِمْ","and (for) their consuming"],["أَمْوَٰلَ","wealth"],["ٱلنَّاسِ","(of) the people"],["بِٱلْبَـٰطِلِ ۚ","wrongfully"],["وَأَعْتَدْنَا","And We have prepared"],["لِلْكَـٰفِرِينَ","for the disbelievers"],["مِنْهُمْ","among them"],["عَذَابًا","a punishment"],["أَلِيمًۭا","painful"]]],"655":["(Tetapi orang-orang yang mendalam) artinya kukuh dan mantap (ilmunya di antara mereka) seperti Abdullah bin Salam (dan orang-orang mukmin) dari golongan Muhajirin dan Ansar (mereka beriman pada apa yang diturunkan kepadamu dan apa-apa yang diturunkan sebelummu) di antara kitab-kitab (sedangkan orang-orang yang mendirikan salat) manshub karena pujian, dan ada pula yang membacanya dengan marfu` (dan membayar zakat serta orang-orang yang beriman kepada Allah dan hari akhir, mereka itulah yang akan Kami beri) fi'ilnya dibaca dengan nun atau dengan ya (pahala yang besar) yakni surga.",[["لَّـٰكِنِ","But"],["ٱلرَّٰسِخُونَ","the ones who are firm"],["فِى","in"],["ٱلْعِلْمِ","the knowledge"],["مِنْهُمْ","among them"],["وَٱلْمُؤْمِنُونَ","and the believers"],["يُؤْمِنُونَ","believe"],["بِمَآ","in what"],["أُنزِلَ","(is) revealed"],["إِلَيْكَ","to you"],["وَمَآ","and what"],["أُنزِلَ","was revealed"],["مِن","from"],["قَبْلِكَ ۚ","before you"],["وَٱلْمُقِيمِينَ","And the ones who establish"],["ٱلصَّلَوٰةَ ۚ","the prayer"],["وَٱلْمُؤْتُونَ","and the ones who give"],["ٱلزَّكَوٰةَ","the zakah"],["وَٱلْمُؤْمِنُونَ","and the ones who believe"],["بِٱللَّهِ","in Allah"],["وَٱلْيَوْمِ","and the Day"],["ٱلْـَٔاخِرِ","the Last "],["أُو۟لَـٰٓئِكَ","those"],["سَنُؤْتِيهِمْ","We will give them"],["أَجْرًا","a reward"],["عَظِيمًا","great"]]],"656":["(Sesungguhnya Kami telah menurunkan wahyu kepadamu sebagaimana Kami telah menurunkannya kepada Nuh dan nabi-nabi sesudahnya dan) seperti (telah Kami turunkan kepada Ibrahim, Ismail, Ishak) yakni kedua putranya (serta Yakub) bin Ishak (dan anak-anaknya) yakni anak-anak Yakub (serta Isa, Ayub, Yunus, Harun, Sulaiman dan Kami datangkan kepada) bapaknya, yakni bapak dari Sulaiman (Daud Zabur) dibaca dengan fathah hingga artinya ialah nama kitab yang diturunkan, dan ada pula yang membaca dengan marfu` yaitu mashdar yang berarti mazbuura artinya yang tertulis.",[["۞ إِنَّآ","Indeed, We"],["أَوْحَيْنَآ","have revealed"],["إِلَيْكَ","to you"],["كَمَآ","as"],["أَوْحَيْنَآ","We revealed"],["إِلَىٰ","to"],["نُوحٍۢ","Nuh"],["وَٱلنَّبِيِّـۧنَ","and the Prophets"],["مِنۢ","from"],["بَعْدِهِۦ ۚ","after him"],["وَأَوْحَيْنَآ","and We revealed"],["إِلَىٰٓ","to"],["إِبْرَٰهِيمَ","Ibrahim"],["وَإِسْمَـٰعِيلَ","and Ishmael"],["وَإِسْحَـٰقَ","and Isaac"],["وَيَعْقُوبَ","and Yaqub"],["وَٱلْأَسْبَاطِ","and the tribes"],["وَعِيسَىٰ","and Isa"],["وَأَيُّوبَ","and Ayyub"],["وَيُونُسَ","and Yunus"],["وَهَـٰرُونَ","and Harun"],["وَسُلَيْمَـٰنَ ۚ","and Sulaiman"],["وَءَاتَيْنَا","and We gave"],["دَاوُۥدَ","(to) Dawood"],["زَبُورًۭا","the Zaboor"]]],"657":["(Dan) telah Kami utus (rasul-rasul yang telah Kami kisahkan tentang mereka kepadamu dulu, dan rasul-rasul yang belum Kami kisahkan). Diriwayatkan bahwa Allah swt. mengirim delapan ribu orang nabi, empat ribu dari kalangan Bani Israel dan empat ribu lagi dari kalangan manusia lainnya ini dikatakan oleh Syekh dalam surah Ghafir. (Dan Allah telah berbicara dengan Musa sebenar berbicara) artinya secara langsung.",[["وَرُسُلًۭا","And Messengers"],["قَدْ","surely"],["قَصَصْنَـٰهُمْ","We (have) mentioned them"],["عَلَيْكَ","to you"],["مِن","from"],["قَبْلُ","before"],["وَرُسُلًۭا","and Messengers"],["لَّمْ","not"],["نَقْصُصْهُمْ","We (have) mentioned them"],["عَلَيْكَ ۚ","to you"],["وَكَلَّمَ","And spoke"],["ٱللَّهُ","Allah"],["مُوسَىٰ","(to) Musa"],["تَكْلِيمًۭا","(in a) conversation"]]],"658":["(Yaitu rasul-rasul) menjadi badal bagi rasul-rasul yang sebelumnya (selalu pembawa berita gembira) dengan diberinya pahala kepada orang yang beriman (dan penyampaian peringatan) dengan adanya siksa kepada orang yang ingkar. Mereka Kami utus itu ialah (agar tidak ada lagi bagi manusia terhadap Allah alasan) yang dapat dikemukakan (setelah) pengiriman (rasul-rasul itu) kepada mereka, misalnya dengan mengatakan, \"Wahai Tuhan kami! Kenapa tidak Tuhan kirim kepada kami seorang rasul agar kami dapat mengikuti ayat-ayat-Mu dan menjadi orang-orang beriman!\" Maka Tuhan pun telah lebih dulu mengirimkan mereka untuk mematahkan alasan mereka tadi (Dan Allah Maha Tangguh) dalam kerajaan-Nya (lagi Maha Bijaksana) dalam perbuatan-Nya. Ayat berikut diturunkan tatkala orang-orang Yahudi ditanyai orang mengenai kenabian Muhammad saw. lalu mereka ingkari:",[["رُّسُلًۭا","Messengers"],["مُّبَشِّرِينَ","bearers of glad tidings"],["وَمُنذِرِينَ","and warners"],["لِئَلَّا","so that not"],["يَكُونَ","there is"],["لِلنَّاسِ","for mankind"],["عَلَى","against"],["ٱللَّهِ","Allah"],["حُجَّةٌۢ","any argument"],["بَعْدَ","after"],["ٱلرُّسُلِ ۚ","the Messengers"],["وَكَانَ","And is"],["ٱللَّهُ","Allah"],["عَزِيزًا","All-Mighty"],["حَكِيمًۭا","All-Wise"]]],"659":["(Tetapi Allah menyaksikan) artinya tentang kenabianmu (dengan apa yang diturunkan-Nya kepadamu) berupa Alquran yang menjadi mukjizat itu (diturunkan-Nya) sebagai hasil (dari ilmu-Nya) atau memuat ilmu-Nya (dan malaikat-malaikat pun menjadi saksi) pula atas kenabianmu itu. (Dan cukuplah Allah sebagai saksi)-nya.",[["لَّـٰكِنِ","But"],["ٱللَّهُ","Allah"],["يَشْهَدُ","bears witness"],["بِمَآ","to what"],["أَنزَلَ","He (has) revealed"],["إِلَيْكَ ۖ","to you"],["أَنزَلَهُۥ","He has sent it down"],["بِعِلْمِهِۦ ۖ","with His Knowledge"],["وَٱلْمَلَـٰٓئِكَةُ","and the Angels"],["يَشْهَدُونَ ۚ","bear witness"],["وَكَفَىٰ","And is sufficient"],["بِٱللَّهِ","Allah"],["شَهِيدًا","(as) a Witness"]]],"660":["(Sesungguhnya orang-orang yang kafir) kepada Allah (dan menghalang-halangi) manusia (dari jalan Allah) artinya dari agama Islam dengan menyembunyikan ciri-ciri Nabi Muhammad saw.; maksudnya ialah orang-orang Yahudi (maka sesungguhnya mereka telah sesat sejauh-jauhnya) dari kebenaran.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["وَصَدُّوا۟","and hinder"],["عَن","from"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["قَدْ","surely"],["ضَلُّوا۟","they have strayed"],["ضَلَـٰلًۢا","straying"],["بَعِيدًا","far away"]]],"661":["(Sesungguhnya orang-orang yang kafir) kepada Allah (dan berlaku aniaya) kepada nabi-Nya dengan menyembunyikan ciri-cirinya itu (maka Allah sekali-kali tidak akan mengampuni mereka dan tidak pula akan menunjukkan kepada mereka suatu jalan) di antara jalan-jalan yang banyak ini.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["وَظَلَمُوا۟","and did wrong"],["لَمْ","not"],["يَكُنِ","will"],["ٱللَّهُ","Allah"],["لِيَغْفِرَ","[to] forgive"],["لَهُمْ","them"],["وَلَا","and not"],["لِيَهْدِيَهُمْ","He will guide them"],["طَرِيقًا","(to) a way"]]],"662":["(Kecuali jalan neraka Jahanam) maksudnya jalan menuju ke sana (kekal mereka) artinya ditakdirkan kekal (di dalamnya) jika mereka telah memasukinya (buat selama-lamanya. Dan yang demikian itu bagi Allah mudah) artinya gampang dan tidak sulit adanya.",[["إِلَّا","Except"],["طَرِيقَ","(the) way"],["جَهَنَّمَ","(to) Hell"],["خَـٰلِدِينَ","abiding"],["فِيهَآ","in it"],["أَبَدًۭا ۚ","forever"],["وَكَانَ","And is"],["ذَٰلِكَ","that"],["عَلَى","for"],["ٱللَّهِ","Allah"],["يَسِيرًۭا","easy"]]],"663":["(Hai manusia) maksudnya warga Mekah (sesungguhnya telah datang kepadamu rasul) yakni Muhammad saw. (membawa kebenaran dari Tuhanmu, maka berimanlah kamu) kepadanya (dan usahakanlah yang terbaik bagi kamu) dari apa yang melingkungimu (Dan jika kamu kafir) kepadanya (maka bagi-Nya apa yang di langit dan yang di bumi) baik sebagai milik maupun sebagai makhluk dan hamba hingga tidaklah merugikan kepada-Nya kekafiranmu itu (Dan Allah Maha Mengetahui) terhadap makhluk-Nya (lagi Maha Bijaksana) mengenai perbuatan-Nya terhadap mereka.",[["يَـٰٓأَيُّهَا","O"],["ٱلنَّاسُ","mankind"],["قَدْ","Surely"],["جَآءَكُمُ","has come to you"],["ٱلرَّسُولُ","the Messenger"],["بِٱلْحَقِّ","with the truth"],["مِن","from"],["رَّبِّكُمْ","your Lord"],["فَـَٔامِنُوا۟","so believe"],["خَيْرًۭا","(it is) better"],["لَّكُمْ ۚ","for you"],["وَإِن","But if"],["تَكْفُرُوا۟","you disbelieve"],["فَإِنَّ","then indeed"],["لِلَّهِ","to Allah (belongs)"],["مَا","whatever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَٱلْأَرْضِ ۚ","and the earth"],["وَكَانَ","And is"],["ٱللَّهُ","Allah"],["عَلِيمًا","All-Knowing"],["حَكِيمًۭا","All-Wise"]]],"664":["(Hai Ahli kitab) maksudnya kitab Injil (janganlah kamu melampaui batas dalam agamamu dan janganlah kamu katakan terhadap Allah kecuali) ucapan (yang benar) yaitu menyucikan-Nya dari kemusyrikan dan mempunyai anak. (Sesungguhnya Almasih Isa putra Maryam itu adalah utusan Allah dan kalimat-Nya yang diucapkan-Nya) atau disampaikan-Nya (kepada Maryam dan roh) artinya yang mempunyai roh (daripada-Nya) diidhafatkan kepada Allah swt. demi untuk memuliakan-Nya dan bukanlah sebagai dugaan kamu bahwa dia adalah anak Allah atau Tuhan bersama-Nya atau salah satu dari oknum yang tiga. Karena sesuatu yang mempunyai roh itu tersusun sedangkan Tuhan Maha Suci dari tersusun dan dari dinisbatkannya tersusun itu kepada-Nya (Maka berimanlah kamu kepada Allah dan kepada rasul-rasul-Nya dan janganlah kamu katakan) bahwa Tuhan itu (tiga) yakni Allah, Isa dan ibunya (hentikanlah) demikian itu (dan perbuatlah yang lebih baik bagi kamu) yakni bertauhid (Sesungguhnya Allah Tuhan Yang Maha Esa Maha Suci Dia) artinya bersih dan terhindar (dari mempunyai anak. Bagi-Nya apa yang terdapat di langit dan yang di bumi) baik sebagai makhluk maupun sebagai milik dan hamba sedangkan pemiliknya itu bertentangan dengan mempunyai anak (Dan cukuplah Allah sebagai wakil) atau saksi atas demikian itu.",[["يَـٰٓأَهْلَ","O People"],["ٱلْكِتَـٰبِ","(of) the Book"],["لَا","(Do) not"],["تَغْلُوا۟","commit excess"],["فِى","in"],["دِينِكُمْ","your religion"],["وَلَا","and (do) not"],["تَقُولُوا۟","say"],["عَلَى","about"],["ٱللَّهِ","Allah"],["إِلَّا","except"],["ٱلْحَقَّ ۚ","the truth"],["إِنَّمَا","Only"],["ٱلْمَسِيحُ","the Messiah"],["عِيسَى","Isa"],["ٱبْنُ","son"],["مَرْيَمَ","(of) Maryam"],["رَسُولُ","(was) a Messenger"],["ٱللَّهِ","(of) Allah"],["وَكَلِمَتُهُۥٓ","and His word"],["أَلْقَىٰهَآ","which He conveyed"],["إِلَىٰ","to"],["مَرْيَمَ","Maryam"],["وَرُوحٌۭ","and a spirit"],["مِّنْهُ ۖ","from Him"],["فَـَٔامِنُوا۟","So believe"],["بِٱللَّهِ","in Allah"],["وَرُسُلِهِۦ ۖ","and His Messengers"],["وَلَا","And (do) not"],["تَقُولُوا۟","say"],["ثَلَـٰثَةٌ ۚ","Three"],["ٱنتَهُوا۟","desist"],["خَيْرًۭا","(it is) better"],["لَّكُمْ ۚ","for you"],["إِنَّمَا","Only"],["ٱللَّهُ","Allah"],["إِلَـٰهٌۭ","(is) God"],["وَٰحِدٌۭ ۖ","One"],["سُبْحَـٰنَهُۥٓ","Glory be to Him"],["أَن","That"],["يَكُونَ","He (should) have"],["لَهُۥ","for Him"],["وَلَدٌۭ ۘ","a son"],["لَّهُۥ","To Him (belongs)"],["مَا","whatever"],["فِى","(is) in"],["ٱلسَّمَـٰوَٰتِ","the heavens"],["وَمَا","and whatever"],["فِى","(is) in"],["ٱلْأَرْضِ ۗ","the earth"],["وَكَفَىٰ","And is sufficient"],["بِٱللَّهِ","Allah"],["وَكِيلًۭا","(as) a Disposer of affairs"]]],"665":["(Almasih tidak merasa malu) maksudnya Almasih yang kamu katakan sebagai Tuhan itu tidak merasa enggan dan takabur (menjadi hamba bagi Allah dan tidak pula enggan malaikat-malaikat yang terdekat) kepada Allah mereka juga tidak malu untuk menjadi hamba-Nya. Ini suatu kalimat selang yang terbaik yang dikemukakan untuk menolak anggapan sementara orang bahwa mereka adalah Tuhan atau putri-putri Allah sebagaimana kalimat yang sebelumnya digunakan untuk menolak anggapan kaum Nasrani bahwa Isa adalah putra-Nya. (Siapa yang enggan untuk menyembah-Nya dan menyombongkan diri maka kelak Allah akan mengumpulkan mereka semua kepada-Nya) yakni di akhirat.",[["لَّن","Never"],["يَسْتَنكِفَ","will disdain"],["ٱلْمَسِيحُ","the Messiah"],["أَن","to"],["يَكُونَ","be"],["عَبْدًۭا","a slave"],["لِّلَّهِ","of Allah"],["وَلَا","and not"],["ٱلْمَلَـٰٓئِكَةُ","the Angels"],["ٱلْمُقَرَّبُونَ ۚ","the ones who are near (to Allah)"],["وَمَن","And whoever"],["يَسْتَنكِفْ","disdains"],["عَنْ","from"],["عِبَادَتِهِۦ","His worship"],["وَيَسْتَكْبِرْ","and is arrogant"],["فَسَيَحْشُرُهُمْ","then He will gather them"],["إِلَيْهِ","towards Him"],["جَمِيعًۭا","all together"]]],"666":["(Adapun orang-orang yang beriman dan beramal saleh maka Allah akan menyempurnakan ganjaran mereka) artinya pahala dari amal perbuatan mereka itu (dan menambah untuk mereka dari karunia-Nya) yakni yang belum pernah dilihat oleh mata, tidak didengar telinga dan tidak pula terdetik dalam hati manusia. (Adapun orang-orang yang malu dan menyombongkan diri) dari mengabdikan diri kepada-Nya (maka akan disiksa-Nya mereka dengan siksaan yang pedih) atau menyakitkan yaitu siksa neraka (dan mereka tidak akan memperoleh bagian bagi diri mereka selain daripada Allah, pelindung) yang akan melindungi diri mereka (dan tidak pula pembela) yang akan menolong mereka.",[["فَأَمَّا","Then as for"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed"],["وَعَمِلُوا۟","and did"],["ٱلصَّـٰلِحَـٰتِ","the righteous deeds"],["فَيُوَفِّيهِمْ","then He will give them in full"],["أُجُورَهُمْ","their reward"],["وَيَزِيدُهُم","and give them more"],["مِّن","from"],["فَضْلِهِۦ ۖ","His Bounty"],["وَأَمَّا","And as for"],["ٱلَّذِينَ","those who"],["ٱسْتَنكَفُوا۟","disdained"],["وَٱسْتَكْبَرُوا۟","and were arrogant"],["فَيُعَذِّبُهُمْ","then He will punish them"],["عَذَابًا","(with) a punishment"],["أَلِيمًۭا","painful"],["وَلَا","and not"],["يَجِدُونَ","will they find"],["لَهُم","for themselves"],["مِّن","from"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["وَلِيًّۭا","any protector"],["وَلَا","and not"],["نَصِيرًۭا","any helper"]]],"667":["(Hai manusia, sesungguhnya telah datang kepadamu keterangan) bukti kebenaran (dari Tuhanmu) yaitu Nabi saw. (dan telah Kami turunkan kepadamu cahaya yang terang) benderang yakni Alquran.",[["يَـٰٓأَيُّهَا","O"],["ٱلنَّاسُ","mankind"],["قَدْ","Surely"],["جَآءَكُم","has come to you"],["بُرْهَـٰنٌۭ","a convincing proof"],["مِّن","from"],["رَّبِّكُمْ","your Lord"],["وَأَنزَلْنَآ","and We (have) sent down"],["إِلَيْكُمْ","to you"],["نُورًۭا","a light"],["مُّبِينًۭا","clear"]]],"668":["(Adapun orang-orang yang beriman kepada Allah dan berpegang teguh kepada-Nya, maka Allah akan memasukkan mereka ke dalam rahmat dan limpahan karunia-Nya dan membimbing mereka ke jalan yang lurus menuju kepada-Nya) yakni agama Islam.",[["فَأَمَّا","So as for"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed"],["بِٱللَّهِ","in Allah"],["وَٱعْتَصَمُوا۟","and held fast"],["بِهِۦ","to Him"],["فَسَيُدْخِلُهُمْ","then He will admit them"],["فِى","in"],["رَحْمَةٍۢ","Mercy"],["مِّنْهُ","from Himself"],["وَفَضْلٍۢ","and Bounty"],["وَيَهْدِيهِمْ","and will guide them"],["إِلَيْهِ","to Himself"],["صِرَٰطًۭا","(on) a way"],["مُّسْتَقِيمًۭا","straight"]]],"669":["(Mereka meminta fatwa kepadamu) mengenai kalalah, yaitu jika seseorang meninggal dunia tanpa meninggalkan bapak dan anak (Katakanlah, \"Allah memberi fatwa kepadamu tentang kalalah; jika seseorang) umru-un menjadi marfu' dengan fi'il yang menafsirkannya (celaka) maksudnya meninggal dunia (dan dia tidak mempunyai anak) dan tidak pula bapak yakni yang dimaksud dengan kalalah tadi (tetapi mempunyai seorang saudara perempuan) baik sekandung maupun sebapak (maka bagi saudaranya yang perempuan itu seperdua dari harta yang ditinggalkannya, dan dia) maksudnya saudaranya yang laki-laki (mewarisi saudaranya yang perempuan) pada seluruh harta peninggalannya (yakni jika ia tidak mempunyai anak). Sekiranya ia mempunyai seorang anak laki-laki, maka tidak satu pun diperolehnya, tetapi jika anaknya itu perempuan, maka saudaranya itu masih memperoleh kelebihan dari bagian anaknya. Dan sekiranya saudara laki-laki atau saudara perempuan itu seibu, maka bagiannya ialah seperenam sebagaimana telah diterangkan di awal surah. (Jika mereka itu) maksudnya saudara perempuan (dua orang) atau lebih, karena ayat ini turun mengenai Jabir; ia meninggal dunia dengan meninggalkan beberapa orang saudara perempuan (maka bagi keduanya dua pertiga dari harta peninggalan) saudara laki-laki mereka. (Dan jika mereka) yakni ahli waris itu terdiri dari (saudara laki-laki dan perempuan, maka bagian seorang laki-laki) di antara mereka (sebanyak bagian dua orang perempuan.\" Allah menerangkan kepadamu syariat-syariat agama-Nya (agar kamu) tidak (sesat. Dan Allah Maha Mengetahui segala sesuatu) di antaranya tentang pembagian harta warisan. Diriwayatkan oleh Bukhari dan Muslim dari Barra bahwa ia merupakan ayat yang terakhir diturunkan, maksudnya mengenai faraid.",[["يَسْتَفْتُونَكَ","They seek your ruling"],["قُلِ","Say"],["ٱللَّهُ","Allah"],["يُفْتِيكُمْ","gives you a ruling"],["فِى","concerning"],["ٱلْكَلَـٰلَةِ ۚ","the Kalala"],["إِنِ","if"],["ٱمْرُؤٌا۟","a man"],["هَلَكَ","died"],["لَيْسَ","(and) not"],["لَهُۥ","he has"],["وَلَدٌۭ","a child"],["وَلَهُۥٓ","and he has"],["أُخْتٌۭ","a sister"],["فَلَهَا","then for her"],["نِصْفُ","(is) a half"],["مَا","(of) what"],["تَرَكَ ۚ","he left"],["وَهُوَ","And he"],["يَرِثُهَآ","will inherit from her"],["إِن","if"],["لَّمْ","not"],["يَكُن","is"],["لَّهَا","for her"],["وَلَدٌۭ ۚ","a child"],["فَإِن","But if"],["كَانَتَا","there were"],["ٱثْنَتَيْنِ","two females"],["فَلَهُمَا","then for them"],["ٱلثُّلُثَانِ","two thirds"],["مِمَّا","of what"],["تَرَكَ ۚ","he left"],["وَإِن","But if"],["كَانُوٓا۟","they were"],["إِخْوَةًۭ","brothers and sisters"],["رِّجَالًۭا","men"],["وَنِسَآءًۭ","and women"],["فَلِلذَّكَرِ","then the male will have"],["مِثْلُ","like"],["حَظِّ","share"],["ٱلْأُنثَيَيْنِ ۗ","(of) the two females"],["يُبَيِّنُ","makes clear"],["ٱللَّهُ","Allah"],["لَكُمْ","to you"],["أَن","lest"],["تَضِلُّوا۟ ۗ","you go astray"],["وَٱللَّهُ","And Allah"],["بِكُلِّ","of every"],["شَىْءٍ","thing"],["عَلِيمٌۢ","(is) All-Knower"]]],"670":["(Hai orang-orang yang beriman, penuhilah olehmu perjanjian itu) baik perjanjian yang terpatri di antara kamu dengan Allah maupun dengan sesama manusia. (Dihalalkan bagi kamu binatang ternak) artinya halal memakan unta, sapi dan kambing setelah hewan itu disembelih (kecuali apa yang dibacakan padamu) tentang pengharamannya dalam ayat, \"Hurrimat `alaikumul maitatu...\" Istitsna` atau pengecualian di sini munqathi` atau terputus tetapi dapat pula muttashil, misalnya yang diharamkan karena mati dan sebagainya (tanpa menghalalkan berburu ketika kamu mengerjakan haji) atau berihram; ghaira dijadikan manshub karena menjadi hal bagi dhamir yang terdapat pada lakum. (Sesungguhnya Allah menetapkan hukum menurut yang dikehendaki-Nya) baik menghalalkan maupun mengharamkannya tanpa seorang pun yang dapat menghalangi-Nya.",[["يَـٰٓأَيُّهَا","O"],["ٱلَّذِينَ","you (who)"],["ءَامَنُوٓا۟","believe"],["أَوْفُوا۟","Fulfil"],["بِٱلْعُقُودِ ۚ","the contracts"],["أُحِلَّتْ","Are made lawful"],["لَكُم","for you"],["بَهِيمَةُ","the quadruped"],["ٱلْأَنْعَـٰمِ","(of) the grazing livestock"],["إِلَّا","except"],["مَا","what"],["يُتْلَىٰ","is recited"],["عَلَيْكُمْ","on you"],["غَيْرَ","not"],["مُحِلِّى","being permitted"],["ٱلصَّيْدِ","(to) hunt"],["وَأَنتُمْ","while you"],["حُرُمٌ ۗ","(are in) Ihram"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يَحْكُمُ","decrees"],["مَا","what"],["يُرِيدُ","He wills"]]],"671":["(Hai orang-orang yang beriman, janganlah kamu melanggar syiar-syiar Allah) jamak sya`iiratun; artinya upacara-upacara agama-Nya. Melanggar yaitu dengan berburu di waktu ihram (dan jangan pula melanggar bulan haram) dengan melakukan peperangan padanya (dan jangan mengganggu binatang-binatang hadya) yakni hewan yang dihadiahkan buat tanah suci (serta binatang-binatang berkalung) jamak dari qilaadatun; artinya binatang yang diberi kalung dengan kayu-kayuan yang terdapat di tanah suci sebagai tanda agar ia aman, maka janganlah ada yang mengganggu baik hewan-hewan itu sendiri maupun para pemiliknya (jangan pula) kamu halalkan atau kamu ganggu (orang-orang yang berkunjung) atau menuju (Baitulharam) dengan memerangi mereka (sedangkan mereka mencari karunia) artinya rezeki (dari Tuhan mereka) dengan berniaga (dan keridaan) daripada-Nya di samping berkunjung ke Baitullah tidak seperti pengertian mereka yang salah itu. Ayat ini dimansukh oleh ayat Bara`ah. (Dan apabila kamu telah selesai) dari ihram (maka perintahlah berburu) perintah di sini berarti ibahah atau memperbolehkan (dan sekali-kali janganlah kamu terdorong oleh kebencian) dibaca syana-aanu atau syan-aanu berarti kebencian atau kemarahan (kepada suatu kaum disebabkan mereka telah menghalangi kamu dari Masjidilharam untuk berbuat aniaya) kepada mereka dengan pembunuhan dan sebagainya. (Bertolong-tolonglah kamu dalam kebaikan) dalam mengerjakan yang dititahkan (dan ketakwaan) dengan meninggalkan apa-apa yang dilarang (dan janganlah kamu bertolong-tolongan) pada ta`aawanu dibuang salah satu di antara dua ta pada asalnya (dalam berbuat dosa) atau maksiat (dan pelanggaran) artinya melampaui batas-batas ajaran Allah. (Dan bertakwalah kamu kepada Allah) takutlah kamu kepada azab siksa-Nya dengan menaati-Nya (sesungguhnya Allah amat berat siksa-Nya) bagi orang yang menentang-Nya.",[["يَـٰٓأَيُّهَا","O"],["ٱلَّذِينَ","you (who)"],["ءَامَنُوا۟","believe"],["لَا","(Do) not"],["تُحِلُّوا۟","violate"],["شَعَـٰٓئِرَ","(the) rites"],["ٱللَّهِ","(of) Allah"],["وَلَا","and not"],["ٱلشَّهْرَ","the month"],["ٱلْحَرَامَ","the sacred"],["وَلَا","and not"],["ٱلْهَدْىَ","the sacrificial animals"],["وَلَا","and not"],["ٱلْقَلَـٰٓئِدَ","the garlanded"],["وَلَآ","and not"],["ءَآمِّينَ","(those) coming"],["ٱلْبَيْتَ","(to) the House"],["ٱلْحَرَامَ","the Sacred"],["يَبْتَغُونَ","seeking"],["فَضْلًۭا","Bounty"],["مِّن","of"],["رَّبِّهِمْ","their Lord"],["وَرِضْوَٰنًۭا ۚ","and good pleasure"],["وَإِذَا","And when"],["حَلَلْتُمْ","you come out of Ihram"],["فَٱصْطَادُوا۟ ۚ","then (you may) hunt"],["وَلَا","And let not"],["يَجْرِمَنَّكُمْ","incite you"],["شَنَـَٔانُ","(the) hatred"],["قَوْمٍ","(for) a people"],["أَن","as"],["صَدُّوكُمْ","they stopped you"],["عَنِ","from"],["ٱلْمَسْجِدِ","Al-Masjid"],["ٱلْحَرَامِ","Al-Haraam"],["أَن","that"],["تَعْتَدُوا۟ ۘ","you commit transgression"],["وَتَعَاوَنُوا۟","And help one another"],["عَلَى","in"],["ٱلْبِرِّ","[the] righteousness"],["وَٱلتَّقْوَىٰ ۖ","and [the] piety"],["وَلَا","but (do) not"],["تَعَاوَنُوا۟","help one another"],["عَلَى","in"],["ٱلْإِثْمِ","[the] sin"],["وَٱلْعُدْوَٰنِ ۚ","and [the] transgression"],["وَٱتَّقُوا۟","And fear"],["ٱللَّهَ ۖ","Allah"],["إِنَّ","indeed"],["ٱللَّهَ","Allah"],["شَدِيدُ","(is) severe"],["ٱلْعِقَابِ","(in) [the] punishment"]]],"672":["(Diharamkan bagimu bangkai) yakni memakannya (darah) yang mengalir seperti pada binatang ternak (daging babi, hewan yang disembelih karena selain Allah) misalnya disembelih atas nama lain-Nya (yang tercekik) yang mati karena tercekik (yang dipukul) yang dibunuh dengan jalan memukulnya (yang jatuh) dari atas ke bawah lalu mati (yang ditanduk) yang mati karena tandukan lainnya (yang diterkam oleh binatang buas kecuali yang sempat kamu sembelih) maksudnya yang kamu dapati masih bernyawa dari macam-macam yang disebutkan itu lalu kamu sembelih (dan yang disembelih atas) nama (berhala) jamak dari nishab; artinya patung (dan mengundi nasib) artinya menentukan bagian dan keputusan (dengan anak panah) azlaam jamak dari zalam atau zulam; artinya anak panah yang belum diberi bulu dan ujungnya tidak bermata. Anak panah itu ada tujuh buah disimpan oleh pengurus Kakbah dan padanya terdapat tanda-tanda. Maka tanda-tanda itulah yang mereka ambil sebagai pedoman, jika disuruh mereka lakukan dan jika dilarang mereka hentikan. (Demikian itu adalah kefasikan) artinya menyimpang dari ketaatan. Ayat ini turun pada hari Arafah masa haji wadak, yaitu haji terakhir yang dilakukan oleh Nabi Muhammad saw. (Pada hari ini orang-orang kafir telah putus-asa terhadap agamamu) untuk mengembalikan kamu menjadi murtad setelah mereka melihat kamu telah kuat (maka janganlah kamu takut kepada mereka dan takutlah pada-Ku. Pada hari ini telah Kusempurnakan untukmu agamamu) yakni hukum-hukum halal maupun haram yang tidak diturunkan lagi setelahnya hukum-hukum dan kewajiban-kewajibannya (dan telah Kucukupkan padamu nikmat karunia-Ku) yakni dengan menyempurnakannya dan ada pula yang mengatakan dengan memasuki kota Mekah dalam keadaan aman (dan telah Kuridai) artinya telah Kupilih (Islam itu sebagai agama kalian. Maka siapa terpaksa karena kelaparan) untuk memakan sesuatu yang haram lalu dimakannya (tanpa cenderung) atau sengaja (berbuat dosa) atau maksiat (maka sesungguhnya Allah Maha Pengampun) terhadapnya atas perbuatan memakannya itu (lagi Maha Pengasih) kepadanya dalam memperbolehkannya. Berbeda halnya dengan orang yang cenderung atau sengaja berbuat dosa, misalnya penyamun atau pemberontak, maka tidak halal baginya memakan itu.",[["حُرِّمَتْ","Are made unlawful"],["عَلَيْكُمُ","on you"],["ٱلْمَيْتَةُ","the dead animals"],["وَٱلدَّمُ","and the blood"],["وَلَحْمُ","and flesh"],["ٱلْخِنزِيرِ","(of) the swine"],["وَمَآ","and what"],["أُهِلَّ","has been dedicated"],["لِغَيْرِ","to other than"],["ٱللَّهِ","Allah"],["بِهِۦ","[on it]"],["وَٱلْمُنْخَنِقَةُ","and that which is strangled (to death)"],["وَٱلْمَوْقُوذَةُ","and that which is hit fatally"],["وَٱلْمُتَرَدِّيَةُ","and that which has a fatal fall"],["وَٱلنَّطِيحَةُ","and that which is gored by horns"],["وَمَآ","and that which"],["أَكَلَ","ate (it)"],["ٱلسَّبُعُ","the wild animal"],["إِلَّا","except"],["مَا","what"],["ذَكَّيْتُمْ","you slaughtered"],["وَمَا","and what"],["ذُبِحَ","is sacrificed"],["عَلَى","on"],["ٱلنُّصُبِ","the stone altars"],["وَأَن","and that"],["تَسْتَقْسِمُوا۟","you seek division"],["بِٱلْأَزْلَـٰمِ ۚ","by divining arrows "],["ذَٰلِكُمْ","that"],["فِسْقٌ ۗ","(is) grave disobedience"],["ٱلْيَوْمَ","This day"],["يَئِسَ","(have) despaired"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["مِن","of"],["دِينِكُمْ","your religion"],["فَلَا","so (do) not"],["تَخْشَوْهُمْ","fear them"],["وَٱخْشَوْنِ ۚ","but fear Me"],["ٱلْيَوْمَ","This day"],["أَكْمَلْتُ","I have perfected"],["لَكُمْ","for you"],["دِينَكُمْ","your religion"],["وَأَتْمَمْتُ","and I have completed"],["عَلَيْكُمْ","upon you"],["نِعْمَتِى","My Favor"],["وَرَضِيتُ","and I have approved"],["لَكُمُ","for you"],["ٱلْإِسْلَـٰمَ","[the] Islam"],["دِينًۭا ۚ","(as) a religion"],["فَمَنِ","But whoever"],["ٱضْطُرَّ","(is) forced"],["فِى","by"],["مَخْمَصَةٍ","hunger"],["غَيْرَ","(and) not"],["مُتَجَانِفٍۢ","inclining"],["لِّإِثْمٍۢ ۙ","to sin"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"673":["(Mereka menanyakan kepadamu) hai Muhammad (Apakah yang dihalalkan bagi mereka) di antara makanan. (Katakanlah, \"Dihalalkan bagimu yang baik-baik) yang enak-enak atau yang halal (dan) hasil buruan (dari binatang-binatang buas yang telah kamu ajar) seperti anjing, serigala dan burung (dengan melatihnya berburu) hal dari kallabtal kalba pakai tasydid pada lam; artinya biasa kamu lepas berburu (kamu ajar mereka itu) hal dari dhamir mukallibiina; artinya kamu latih mereka itu (menurut apa yang diajarkan Allah kepadamu) tentang cara berburu (maka makanlah apa-apa yang ditangkapnya untukmu) mereka membunuh buruan tanpa memakannya. Berbeda halnya dengan yang tidak terlatih, maka tangkapannya itu tidak halal. Sebagai ciri-cirinya bila dilepas ia berangkat dan bila dicegah ia berhenti serta ditahannya buruan itu dan tidak dimakannya. Sekurang-kurangnya untuk mengetahui hal itu dibutuhkan pengamatan sebanyak tiga kali. Jika buruan itu dimakannya, berarti tidak ditangkapnya untuk tuannya, maka tidak halal dimakan sebagaimana tercantum dalam kedua hadis sahih Bukhari dan Muslim. Dalam hadis itu juga disebutkan bahwa hasil panahan jika dilepas dengan menyebut nama Allah, maka sama dengan hasil buruan dari binatang pemburu yang telah dilatih. (Dan sebutlah nama Allah atasnya) ketika melepasnya (serta bertakwalah kepada Allah; sesungguhnya Allah amat cepat perhitungan-Nya.\")",[["يَسْـَٔلُونَكَ","They ask you"],["مَاذَآ","what"],["أُحِلَّ","(is) made lawful"],["لَهُمْ ۖ","for them"],["قُلْ","Say"],["أُحِلَّ","Are made lawful"],["لَكُمُ","for you"],["ٱلطَّيِّبَـٰتُ ۙ","the good things"],["وَمَا","and what"],["عَلَّمْتُم","you have taught"],["مِّنَ","of"],["ٱلْجَوَارِحِ","(your) hunting animals"],["مُكَلِّبِينَ","ones who train animals to hunt"],["تُعَلِّمُونَهُنَّ","you teach them"],["مِمَّا","of what"],["عَلَّمَكُمُ","has taught you"],["ٱللَّهُ ۖ","Allah"],["فَكُلُوا۟","So eat"],["مِمَّآ","of what"],["أَمْسَكْنَ","they catch"],["عَلَيْكُمْ","for you"],["وَٱذْكُرُوا۟","but mention"],["ٱسْمَ","(the) name"],["ٱللَّهِ","(of) Allah"],["عَلَيْهِ ۖ","on it"],["وَٱتَّقُوا۟","and fear"],["ٱللَّهَ ۚ","Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["سَرِيعُ","is swift"],["ٱلْحِسَابِ","(in taking) account"]]],"674":["(Pada hari ini dihalalkan bagimu yang baik-baik) artinya yang enak-enak (Dan makanan-makanan orang-orang yang diberi kitab) maksudnya sembelihan orang-orang Yahudi dan Nasrani (halal bagi kamu dan makananmu) yang kamu sajikan kepada mereka (halal pula bagi mereka. Dan wanita-wanita yang merdeka di antara wanita-wanita mukmin serta wanita-wanita merdeka dari kalangan orang-orang yang diberi kitab sebelum kamu) halal pula kamu kawini (apabila kamu telah membayar maskawin mereka) atau mahar (dengan maksud mengawini mereka) sehingga terpelihara kehormatan (bukan dengan maksud berzina) dengan mereka secara terang-terangan (dan bukan pula untuk mengambil mereka sebagai gundik) atau melakukan perzinaan dengan mereka secara sembunyi-sembunyi. (Dan siapa yang kafir terhadap iman) artinya murtad (maka sungguh telah hapuslah amalnya) amal saleh sebelum itu hingga tidak dianggap diberi pahala (dan ia di akhirat termasuk orang-orang yang merugi) yakni jika ia meninggal dalam keadaan demikian itu.",[["ٱلْيَوْمَ","This day"],["أُحِلَّ","are made lawful"],["لَكُمُ","for you"],["ٱلطَّيِّبَـٰتُ ۖ","the good things"],["وَطَعَامُ","and (the) food"],["ٱلَّذِينَ","(of) those who"],["أُوتُوا۟","were given"],["ٱلْكِتَـٰبَ","the Book"],["حِلٌّۭ","(is) lawful"],["لَّكُمْ","for you"],["وَطَعَامُكُمْ","and your food"],["حِلٌّۭ","(is) lawful"],["لَّهُمْ ۖ","for them"],["وَٱلْمُحْصَنَـٰتُ","And the chaste women"],["مِنَ","from"],["ٱلْمُؤْمِنَـٰتِ","the believers"],["وَٱلْمُحْصَنَـٰتُ","and the chaste women"],["مِنَ","from"],["ٱلَّذِينَ","those who"],["أُوتُوا۟","were given"],["ٱلْكِتَـٰبَ","the Book"],["مِن","from"],["قَبْلِكُمْ","before you"],["إِذَآ","when"],["ءَاتَيْتُمُوهُنَّ","you have given them"],["أُجُورَهُنَّ","their bridal due"],["مُحْصِنِينَ","being chaste"],["غَيْرَ","not"],["مُسَـٰفِحِينَ","being lewd"],["وَلَا","and not"],["مُتَّخِذِىٓ","ones (who are) taking"],["أَخْدَانٍۢ ۗ","secret lovers"],["وَمَن","And whoever"],["يَكْفُرْ","denies"],["بِٱلْإِيمَـٰنِ","the faith "],["فَقَدْ","then surely"],["حَبِطَ","(are) wasted"],["عَمَلُهُۥ","his deeds"],["وَهُوَ","and he"],["فِى","in"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["مِنَ","(will be) among"],["ٱلْخَـٰسِرِينَ","the losers"]]],"675":["(Hai orang-orang yang beriman, jika kamu berdiri) maksudnya hendak berdiri (mengerjakan salat) dan kamu sedang berhadas (maka basuhlah muka dan tanganmu sampai ke siku) artinya termasuk siku itu sebagaimana diterangkan dalam sunah (dan sapulah kepalamu) ba berarti melengketkan, jadi lengketkanlah sapuanmu itu kepadanya tanpa mengalirkan air. Dan ini merupakan isim jenis, sehingga dianggap cukup bila telah tercapai sapuan walaupun secara minimal, yaitu dengan disapunya sebagian rambut. Pendapat ini juga dianut oleh Imam Syafii (dan kakimu) dibaca manshub karena diathafkan kepada aidiyakum; jadi basuhlah tetapi ada pula yang membaca dengan baris di bawah/kasrah dengan diathafkan kepada yang terdekat (sampai dengan kedua mata kaki) artinya termasuk kedua mata kaki itu, sebagaimana diterangkan dalam hadis. Dua mata kaki ialah dua tulang yang tersembul pada setiap pergelangan kaki yang memisah betis dengan tumit. Dan pemisahan di antara tangan dan kaki yang dibasuh dengan rambut yang disapu menunjukkan diharuskannya/wajib berurutan dalam membersihkan anggota wudu itu. Ini juga merupakan pendapat Syafii. Dari sunah diperoleh keterangan tentang wajibnya berniat seperti halnya ibadah-ibadah lainnya. (Dan jika kamu dalam keadaan junub, maka bersucilah) maksudnya mandilah (dan apabila sakit) yang akan bertambah parah dengan menyentuh air (atau dalam perjalanan) musafir (atau kamu kembali dari tempat buang air) artinya berhadas (atau menyentuh wanita) hal ini telah dibicarakan dulu pada surah An-Nisa (lalu kamu tidak memperoleh air) yakni setelah mencarinya (maka bertayamumlah) dengan mencari (tanah yang baik) tanah yang bersih (sapulah muka dan tanganmu) beserta kedua siku (dengan tanah itu) dengan dua kali pukulan. Ba menunjukkan lengket sementara sunah menjelaskan bahwa yang dimaksud ialah hendaklah sapuan itu meliputi kedua anggota secara keseluruhan (Allah tidaklah hendak menyulitkan kamu) dengan kewajiban-kewajiban berwudu, mandi atau tayamum itu (tetapi Dia hendak menyucikan kamu) dari hadas dan dosa (dan hendak menyempurnakan nikmat-Nya kepadamu) yakni dengan Islam dengan menerangkan syariat-syariat agama (semoga kamu bersyukur) atas nikmat-Nya itu.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوٓا۟","believe"],["إِذَا","When"],["قُمْتُمْ","you stand up"],["إِلَى","for"],["ٱلصَّلَوٰةِ","the prayer"],["فَٱغْسِلُوا۟","then wash"],["وُجُوهَكُمْ","your faces"],["وَأَيْدِيَكُمْ","and your hands"],["إِلَى","till"],["ٱلْمَرَافِقِ","the elbows"],["وَٱمْسَحُوا۟","and wipe"],["بِرُءُوسِكُمْ","your heads"],["وَأَرْجُلَكُمْ","and your feet"],["إِلَى","till"],["ٱلْكَعْبَيْنِ ۚ","the ankles"],["وَإِن","But if"],["كُنتُمْ","you are"],["جُنُبًۭا","(in) a state of ceremonial impurity"],["فَٱطَّهَّرُوا۟ ۚ","then purify yourselves"],["وَإِن","But if"],["كُنتُم","you are"],["مَّرْضَىٰٓ","ill"],["أَوْ","or"],["عَلَىٰ","on"],["سَفَرٍ","a journey"],["أَوْ","or"],["جَآءَ","has come"],["أَحَدٌۭ","anyone"],["مِّنكُم","of you"],["مِّنَ","from"],["ٱلْغَآئِطِ","the toilet"],["أَوْ","or"],["لَـٰمَسْتُمُ","has (had) contact"],["ٱلنِّسَآءَ","(with) the women"],["فَلَمْ","and not"],["تَجِدُوا۟","you find"],["مَآءًۭ","water"],["فَتَيَمَّمُوا۟","then do tayyammum"],["صَعِيدًۭا","(with) earth"],["طَيِّبًۭا","clean"],["فَٱمْسَحُوا۟","then wipe"],["بِوُجُوهِكُمْ","your faces"],["وَأَيْدِيكُم","and your hands"],["مِّنْهُ ۚ","with it"],["مَا","Does not"],["يُرِيدُ","intend"],["ٱللَّهُ","Allah"],["لِيَجْعَلَ","to make"],["عَلَيْكُم","for you"],["مِّنْ","any"],["حَرَجٍۢ","difficulty"],["وَلَـٰكِن","but"],["يُرِيدُ","He intends"],["لِيُطَهِّرَكُمْ","to purify you"],["وَلِيُتِمَّ","and to complete"],["نِعْمَتَهُۥ","His Favor"],["عَلَيْكُمْ","upon you"],["لَعَلَّكُمْ","so that you may"],["تَشْكُرُونَ","(be) grateful"]]],"676":["(Dan ingatlah olehmu karunia Allah kepadamu) maksudnya agama Islam (dan perjanjian-Nya yang telah diikat erat-Nya denganmu) artinya yang telah diperbuat-Nya denganmu (ketika kamu mengatakan) kepada Nabi saw. sewaktu baiat kepadanya (Kami dengar dan kami taati) mengenai apa juga yang engkau suruh atau pun larang, baik yang kami sukai maupun yang kami benci (dan bertakwalah kamu kepada Allah) jangan sampai melanggar perjanjian itu (Sesungguhnya Allah Maha Mengetahui isi hati) yakni apa yang terdapat di dalamnya apa lagi yang terdapat di luarnya.",[["وَٱذْكُرُوا۟","And remember"],["نِعْمَةَ","(the) Favor"],["ٱللَّهِ","(of) Allah"],["عَلَيْكُمْ","upon you"],["وَمِيثَـٰقَهُ","and His covenant"],["ٱلَّذِى","which"],["وَاثَقَكُم","He bound you"],["بِهِۦٓ","with [it]"],["إِذْ","when"],["قُلْتُمْ","you said"],["سَمِعْنَا","We heard"],["وَأَطَعْنَا ۖ","and we obeyed"],["وَٱتَّقُوا۟","and fear"],["ٱللَّهَ ۚ","Allah"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["عَلِيمٌۢ","(is) All-Knower"],["بِذَاتِ","of what"],["ٱلصُّدُورِ","(is in) the breasts"]]],"677":["(Hai orang-orang yang beriman, hendaklah kamu selalu berdiri karena Allah) menegakkan kebenaran-kebenaran-Nya (menjadi saksi dengan adil) (dan janganlah kamu terdorong oleh kebencian kepada sesuatu kaum) yakni kepada orang-orang kafir (untuk berlaku tidak adil) hingga kamu menganiaya mereka karena permusuhan mereka itu. (Berlaku adillah kamu) baik terhadap lawan maupun terhadap kawan (karena hal itu) artinya keadilan itu (lebih dekat kepada ketakwaan. Dan bertakwalah kepada Allah, sesungguhnya Allah Maha Mengetahui apa yang kamu kerjakan) sehingga kamu akan menerima pembalasan daripadanya.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["كُونُوا۟","Be"],["قَوَّٰمِينَ","steadfast"],["لِلَّهِ","for Allah"],["شُهَدَآءَ","(as) witnesses"],["بِٱلْقِسْطِ ۖ","in justice"],["وَلَا","and let not"],["يَجْرِمَنَّكُمْ","prevent you"],["شَنَـَٔانُ","hatred"],["قَوْمٍ","(of) a people"],["عَلَىٰٓ","[upon]"],["أَلَّا","that not"],["تَعْدِلُوا۟ ۚ","you do justice"],["ٱعْدِلُوا۟","Be just"],["هُوَ","it"],["أَقْرَبُ","(is) nearer"],["لِلتَّقْوَىٰ ۖ","to [the] piety"],["وَٱتَّقُوا۟","And fear"],["ٱللَّهَ ۚ","Allah"],["إِنَّ","indeed"],["ٱللَّهَ","Allah"],["خَبِيرٌۢ","(is) All-Aware"],["بِمَا","of what"],["تَعْمَلُونَ","you do"]]],"678":["(Allah telah menjanjikan kepada orang-orang yang beriman dan yang beramal saleh) suatu janji yang baik (bahwa untuk mereka keampunan dan pahala yang besar) yakni surga.",[["وَعَدَ","Has promised"],["ٱللَّهُ","Allah"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believe"],["وَعَمِلُوا۟","and do"],["ٱلصَّـٰلِحَـٰتِ ۙ","the righteous deeds "],["لَهُم","for them"],["مَّغْفِرَةٌۭ","(is) forgiveness"],["وَأَجْرٌ","and a reward"],["عَظِيمٌۭ","great"]]],"679":["(Sebaliknya orang-orang yang kafir dan mendustakan ayat-ayat Kami mereka itu adalah penduduk neraka.)",[["وَٱلَّذِينَ","And those who"],["كَفَرُوا۟","disbelieve"],["وَكَذَّبُوا۟","and deny"],["بِـَٔايَـٰتِنَآ","Our Signs "],["أُو۟لَـٰٓئِكَ","those"],["أَصْحَـٰبُ","(are the) companions"],["ٱلْجَحِيمِ","(of) the Hellfire"]]],"680":["(Hai orang-orang yang beriman, ingatlah nikmat Allah kepadamu ketika suatu kaum bermaksud) yakni orang-orang Quraisy (hendak memanjangkan tangan mereka kepadamu) buat mencelakakanmu (maka ditahan-Nya tangan mereka daripadamu) dan dilindungi-Nya kamu dari maksud jahat mereka itu (dan bertakwalah kamu kepada Allah dan hendaklah kepada Allah orang-orang mukmin itu bertawakal.)",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["ٱذْكُرُوا۟","Remember"],["نِعْمَتَ","(the) Favor"],["ٱللَّهِ","(of) Allah"],["عَلَيْكُمْ","upon you"],["إِذْ","when"],["هَمَّ","determined"],["قَوْمٌ","a people"],["أَن","that"],["يَبْسُطُوٓا۟","they stretch"],["إِلَيْكُمْ","towards you"],["أَيْدِيَهُمْ","their hands"],["فَكَفَّ","but He restrained"],["أَيْدِيَهُمْ","their hands"],["عَنكُمْ ۖ","from you"],["وَٱتَّقُوا۟","And fear"],["ٱللَّهَ ۚ","Allah"],["وَعَلَى","And upon"],["ٱللَّهِ","Allah"],["فَلْيَتَوَكَّلِ","so let put the trust"],["ٱلْمُؤْمِنُونَ","the believers"]]],"681":["(Dan sesungguhnya Allah telah mengambil perjanjian dari Bani Israel) mengenai apa yang akan disebutkan di belakang nanti (dan telah Kami angkat) terdapat peralihan dari dhamir gaib kepada orang pertama (di antara mereka 12 orang pemimpin) dari setiap suku seorang pemimpin yang akan menjamin dipenuhinya perjanjian itu oleh semua warga, dan kepada mereka (Allah berfirman, \"Sesungguhnya Aku beserta kamu) siap dengan pertolongan dan bantuan. (Demi jika) lam menunjukkan sumpah (kamu mendirikan salat, menunaikan zakat, beriman kepada rasul-rasul-Ku dan memberikan bantuan kepada mereka serta kamu berikan kepada Allah suatu pinjaman yang baik) dengan mengeluarkan nafkah di jalan-Nya (maka akan Kututupi kesalahan-kesalahan kamu dan akan Kumasukkan kamu ke dalam surga yang di bawahnya mengalir sungai-sungai. Maka siapa yang kafir sesudah itu) maksudnya sesudah perjanjian (di antara kamu, sesungguhnya ia telah sesat dari jalan yang lurus.\") dari jalan yang benar. Sawaa` pada asalnya ialah yang pertengahan. Maka mereka langgar perjanjian itu hingga Allah pun berfirman:",[["۞ وَلَقَدْ","And certainly"],["أَخَذَ","took"],["ٱللَّهُ","Allah"],["مِيثَـٰقَ","a Covenant"],["بَنِىٓ","(from the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"],["وَبَعَثْنَا","and We appointed"],["مِنْهُمُ","among them"],["ٱثْنَىْ","two"],["عَشَرَ","(and) ten"],["نَقِيبًۭا ۖ","leaders"],["وَقَالَ","And said"],["ٱللَّهُ","Allah"],["إِنِّى","Indeed, I (am)"],["مَعَكُمْ ۖ","with you"],["لَئِنْ","if"],["أَقَمْتُمُ","you establish"],["ٱلصَّلَوٰةَ","the prayer"],["وَءَاتَيْتُمُ","and give"],["ٱلزَّكَوٰةَ","the zakah"],["وَءَامَنتُم","and you believe"],["بِرُسُلِى","in My Messengers"],["وَعَزَّرْتُمُوهُمْ","and you assist them"],["وَأَقْرَضْتُمُ","and you loan"],["ٱللَّهَ","(to) Allah"],["قَرْضًا","a loan"],["حَسَنًۭا","goodly"],["لَّأُكَفِّرَنَّ","surely I will remove"],["عَنكُمْ","from you"],["سَيِّـَٔاتِكُمْ","your evil deeds"],["وَلَأُدْخِلَنَّكُمْ","and I will surely admit you"],["جَنَّـٰتٍۢ","(to) gardens"],["تَجْرِى","flow"],["مِن","from"],["تَحْتِهَا","underneath them"],["ٱلْأَنْهَـٰرُ ۚ","the rivers"],["فَمَن","But whoever"],["كَفَرَ","disbelieved"],["بَعْدَ","after"],["ذَٰلِكَ","that"],["مِنكُمْ","among you"],["فَقَدْ","then certainly"],["ضَلَّ","he strayed"],["سَوَآءَ","(from) the way"],["ٱلسَّبِيلِ","the right"]]],"682":["(Maka disebabkan mereka melanggar) maa merupakan tambahan (janji itu, Kami kutuk mereka) artinya Kami jauhkan dari rahmat Kami (dan Kami jadikan hati mereka keras) tak hendak lunak untuk menerima keimanan. (Mereka ubah perkataan-perkataan)yang terdapat dalam Taurat berupa sifat-sifat dan ciri-ciri Muhammad (dari tempat-tempatnya) semula yang ditaruh oleh Allah (dan mereka lupakan) tinggalkan (sebagian dari peringatan-peringatan yang telah disampaikan kepada mereka) dalam Taurat mengenai ketaatan kepada Muhammad. (Dan selalulah kamu) perkataan ditujukan kepada Nabi saw. (melihat) secara jelas (pengkhianatan dari mereka) dengan mengingkari janji dan lain-lain (kecuali sedikit di antara mereka) yang masuk Islam. (Maka maafkanlah mereka itu dan biarkanlah, sesungguhnya Allah menyukai orang-orang yang berbuat baik) ini dimansukh oleh ayat perang.",[["فَبِمَا","So for"],["نَقْضِهِم","their breaking"],["مِّيثَـٰقَهُمْ","(of) their covenant"],["لَعَنَّـٰهُمْ","We cursed them"],["وَجَعَلْنَا","and We made"],["قُلُوبَهُمْ","their hearts"],["قَـٰسِيَةًۭ ۖ","hard"],["يُحَرِّفُونَ","They distort"],["ٱلْكَلِمَ","the words"],["عَن","from"],["مَّوَاضِعِهِۦ ۙ","their places"],["وَنَسُوا۟","and forgot"],["حَظًّۭا","a part"],["مِّمَّا","of what"],["ذُكِّرُوا۟","they were reminded"],["بِهِۦ ۚ","of [it]"],["وَلَا","And not"],["تَزَالُ","will you cease"],["تَطَّلِعُ","to discover"],["عَلَىٰ","of"],["خَآئِنَةٍۢ","treachery"],["مِّنْهُمْ","from them"],["إِلَّا","except"],["قَلِيلًۭا","a few"],["مِّنْهُمْ ۖ","of them"],["فَٱعْفُ","But forgive"],["عَنْهُمْ","them"],["وَٱصْفَحْ ۚ","and overlook"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يُحِبُّ","loves"],["ٱلْمُحْسِنِينَ","the good-doers"]]],"683":["(Dan di antara orang-orang yang mengatakan, \"Sesungguhnya kami ini orang-orang Nasrani,\") berkaitan dengan firman-Nya (ada yang telah Kami ambil pula janji mereka) sebagaimana halnya orang-orang Yahudi dari kalangan Bani Israel (maka mereka lupakan sebagian dari peringatan yang telah disampaikan kepada mereka) yakni dalam Injil berupa keimanan dan lain-lain hingga mereka ingkari perjanjian itu (maka Kami bangkitkan di antara mereka permusuhan dan kebencian sampai hari kiamat) dengan pertikaian dan perbedaan keinginan mereka, hingga setiap golongan mengafirkan yang lain (dan Allah akan memberitakan kepada mereka kelak) yakni di akhirat (apa-apa yang mereka perbuat) lalu mendapat pembalasan daripada-Nya.",[["وَمِنَ","And from"],["ٱلَّذِينَ","those who"],["قَالُوٓا۟","said"],["إِنَّا","Indeed we"],["نَصَـٰرَىٰٓ","(are) Christians"],["أَخَذْنَا","We took"],["مِيثَـٰقَهُمْ","their covenant"],["فَنَسُوا۟","but they forgot"],["حَظًّۭا","a part"],["مِّمَّا","of what"],["ذُكِّرُوا۟","they were reminded"],["بِهِۦ","of [it]"],["فَأَغْرَيْنَا","So We aroused"],["بَيْنَهُمُ","between them"],["ٱلْعَدَاوَةَ","[the] enmity"],["وَٱلْبَغْضَآءَ","and [the] hatred"],["إِلَىٰ","till"],["يَوْمِ","(the) Day"],["ٱلْقِيَـٰمَةِ ۚ","(of) the Resurrection"],["وَسَوْفَ","And soon"],["يُنَبِّئُهُمُ","will inform them"],["ٱللَّهُ","Allah"],["بِمَا","of what"],["كَانُوا۟","they used to"],["يَصْنَعُونَ","do"]]],"684":["(Hai Ahli kitab! Sesungguhnya telah datang kepada kamu utusan kami) Muhammad (mengungkapkan kepadamu banyak hal dari apa yang kamu sembunyikan dari Alkitab) yakni kitab Taurat dan Injil seperti ayat tentang rajam dan sifat-sifat Nabi saw. (dan banyak pula yang dibiarkannya) di antara demikian sehingga tidak diungkapkannya jika tidak ada kepentingannya selain dari membukakan rahasia kamu belaka. (Sesungguhnya telah datang kepadamu cahaya dari Allah) itulah dia Nabi saw. (dan kitab) yakni Alquran (yang jelas) nyata.",[["يَـٰٓأَهْلَ","O People"],["ٱلْكِتَـٰبِ","(of) the Book"],["قَدْ","Surely"],["جَآءَكُمْ","has come to you"],["رَسُولُنَا","Our Messenger"],["يُبَيِّنُ","making clear"],["لَكُمْ","to you"],["كَثِيرًۭا","much"],["مِّمَّا","of what"],["كُنتُمْ","you used to"],["تُخْفُونَ","conceal"],["مِنَ","of"],["ٱلْكِتَـٰبِ","the Scripture"],["وَيَعْفُوا۟","and overlooking"],["عَن","of"],["كَثِيرٍۢ ۚ","much"],["قَدْ","Surely"],["جَآءَكُم","has come to you"],["مِّنَ","from"],["ٱللَّهِ","Allah"],["نُورٌۭ","a light"],["وَكِتَـٰبٌۭ","and a Book"],["مُّبِينٌۭ","clear"]]],"685":["(Dengan kitab itu Allah menunjuki orang-orang yang mengikuti keridaan-Nya) maksudnya dengan Alquran dan dengan jalan beriman (ke jalan-jalan keselamatan) jalan yang menyelamatkan mereka (dan mengeluarkan mereka dari kegelapan) yakni kekafiran (kepada cahaya) yakni keimanan (dengan izin-Nya) dengan iradat-Nya (serta membimbing mereka ke jalan yang lurus) yakni agama Islam.",[["يَهْدِى","Guides"],["بِهِ","with it"],["ٱللَّهُ","Allah"],["مَنِ","(those) who"],["ٱتَّبَعَ","seek"],["رِضْوَٰنَهُۥ","His pleasure"],["سُبُلَ","(to the) ways"],["ٱلسَّلَـٰمِ","(of) the peace"],["وَيُخْرِجُهُم","and brings them out"],["مِّنَ","from"],["ٱلظُّلُمَـٰتِ","the darknessess"],["إِلَى","to"],["ٱلنُّورِ","the light"],["بِإِذْنِهِۦ","by His permission"],["وَيَهْدِيهِمْ","and guides them"],["إِلَىٰ","to"],["صِرَٰطٍۢ","(the) way"],["مُّسْتَقِيمٍۢ","(the) straight"]]],"686":["(Sungguh, telah kafirlah orang-orang yang mengatakan, \"Sesungguhnya Allah itu ialah Almasih putra Maryam.\") yang mereka memandangnya sebagai Tuhan. Mereka ini ialah kaum Yakobin suatu sekte dari agama Nasrani (Katakanlah, \"Siapakah yang dapat menolak) menghalangi (akan) siksa (Allah walau sedikit pun, jika Dia hendak membinasakan Almasih putra Maryam itu beserta ibunya dan orang-orang yang ada di bumi keseluruhannya?) Maksudnya tak seorang pun yang mampu menolak kehendak-Nya. Dan sekiranya Almasih itu benar-benar Tuhan tentulah ia akan mampu melakukannya. (Dan milik Allahlah kerajaan langit dan bumi dan apa yang terdapat di antara keduanya. Diciptakan-Nya apa yang disukai-Nya, dan Allah atas segala sesuatu) yang dikehendaki-Nya (Maha Kuasa\").",[["لَّقَدْ","Certainly"],["كَفَرَ","disbelieved "],["ٱلَّذِينَ","those who"],["قَالُوٓا۟","said"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["هُوَ","He"],["ٱلْمَسِيحُ","(is) the Messiah"],["ٱبْنُ","son"],["مَرْيَمَ ۚ","(of) Maryam"],["قُلْ","Say"],["فَمَن","Then who"],["يَمْلِكُ","has power"],["مِنَ","against"],["ٱللَّهِ","Allah"],["شَيْـًٔا","(in) anything"],["إِنْ","if"],["أَرَادَ","He intends"],["أَن","to"],["يُهْلِكَ","destroy"],["ٱلْمَسِيحَ","the Messiah"],["ٱبْنَ","son"],["مَرْيَمَ","(of) Maryam"],["وَأُمَّهُۥ","and his mother"],["وَمَن","and whoever"],["فِى","(is) in"],["ٱلْأَرْضِ","the earth"],["جَمِيعًۭا ۗ","all"],["وَلِلَّهِ","And for Allah"],["مُلْكُ","(is the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَمَا","and what"],["بَيْنَهُمَا ۚ","(is) between both of them"],["يَخْلُقُ","He creates"],["مَا","what"],["يَشَآءُ ۚ","He wills"],["وَٱللَّهُ","and Allah"],["عَلَىٰ","(is) on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌۭ","All-Powerful"]]],"687":["(Kata orang-orang Yahudi dan Nasrani) artinya kata masing-masing golongan itu (\"Kami ini anak-anak Allah) maksudnya seperti anak-anak-Nya dalam keakraban dan kedudukan, sebaliknya Dia tak ubahnya dengan bapak kami dalam kecintaan dan kasih sayang (dan kekasih-kekasih-Nya.\" Katakanlah) kepada mereka hai Muhammad (\"Kalau begitu kenapa Allah menyiksamu karena dosa-dosamu?\") Maksudnya ucapanmu itu bohong, karena biasanya bapak tak mau menyiksa anaknya begitu pula seorang kekasih terhadap orang yang disayanginya (bahkan kamu hanyalah manusia biasa termasuk) golongan makhluk (yang diciptakan-Nya) di antara manusia, sama-sama menerima pahala dan memikul dosa bersama mereka (diampuni-Nya siapa yang dikehendaki-Nya) bagi-Nyalah ampunan (dan disiksa-Nya siapa yang dikehendaki-Nya) untuk disiksa tanpa suatu pun yang akan menghalangi-Nya. (Dan milik Allahlah kerajaan langit dan bumi dan segala apa yang terdapat di antara keduanya dan kepada-Nya tempat kembali).",[["وَقَالَتِ","And said"],["ٱلْيَهُودُ","the Jews"],["وَٱلنَّصَـٰرَىٰ","and the Christians"],["نَحْنُ","We (are)"],["أَبْنَـٰٓؤُا۟","(the) children"],["ٱللَّهِ","(of) Allah"],["وَأَحِبَّـٰٓؤُهُۥ ۚ","and His beloved"],["قُلْ","Say"],["فَلِمَ","Then why"],["يُعَذِّبُكُم","(does He) punish you"],["بِذُنُوبِكُم ۖ","for your sins"],["بَلْ","Nay"],["أَنتُم","you (are)"],["بَشَرٌۭ","human beings"],["مِّمَّنْ","from among (those)"],["خَلَقَ ۚ","He created"],["يَغْفِرُ","He forgives"],["لِمَن","[for] whom"],["يَشَآءُ","He wills"],["وَيُعَذِّبُ","and punishes"],["مَن","whom"],["يَشَآءُ ۚ","He wills"],["وَلِلَّهِ","And for Allah"],["مُلْكُ","(is the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["وَمَا","and whatever"],["بَيْنَهُمَا ۖ","(is) between them"],["وَإِلَيْهِ","and to Him"],["ٱلْمَصِيرُ","(is) the final return"]]],"688":["(Hai Ahli Kitab! Sesungguhnya telah datang kepadamu rasul Kami) yakni Muhammad (menjelaskan kepada kamu) syariat-syariat agama (ketika terputusnya pengiriman rasul-rasul) karena antara dia dengan Isa tak seorang pun rasul yang diutus Allah sedangkan jarak masanya ialah 569 tahun (agar) tidak (kamu katakan) jika kamu disiksa nanti (\"Tidak ada datang kepada kami) min sebagai tambahan (pembawa berita gembira dan tidak pula pembawa peringatan karena sesungguhnya telah datang kepadamu pembawa berita gembira maupun pembawa peringatan itu\") sehingga tak ada kemaafan bagimu lagi! (Dan Allah Maha Kuasa atas segala sesuatu) di antaranya menyiksamu jika kamu tidak taat dan patuh kepada-Nya.",[["يَـٰٓأَهْلَ","O People"],["ٱلْكِتَـٰبِ","(of) the Book"],["قَدْ","Surely"],["جَآءَكُمْ","has come to you"],["رَسُولُنَا","Our Messenger"],["يُبَيِّنُ","he makes clear"],["لَكُمْ","to you"],["عَلَىٰ","[on]"],["فَتْرَةٍۢ","(after) an interval (of cessation)"],["مِّنَ","of"],["ٱلرُّسُلِ","the Messengers"],["أَن","lest"],["تَقُولُوا۟","you say"],["مَا","Not"],["جَآءَنَا","(has) come to us"],["مِنۢ","any"],["بَشِيرٍۢ","bearer of glad tidings"],["وَلَا","and not"],["نَذِيرٍۢ ۖ","a warner"],["فَقَدْ","But surely"],["جَآءَكُم","has come to you"],["بَشِيرٌۭ","a bearer of glad tidings"],["وَنَذِيرٌۭ ۗ","and a warner"],["وَٱللَّهُ","And Allah"],["عَلَىٰ","(is) on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌۭ","All-Powerful"]]],"689":["(Dan) ingatlah (ketika Musa berkata kepada kaumnya, \"Hai kaumku! Ingatlah nikmat Allah kepadamu ketika diangkat-Nya padamu) maksudnya dari golonganmu (para nabi dan dijadikan-Nya kamu sebagai raja-raja) yang mempunyai anak buah dan pelayan (serta diberi-Nya kamu apa yang belum pernah diberikan-Nya kepada seorang pun di antara umat manusia) seperti hidangan dari langit, manna dan salwa, terbelahnya lautan dan lain-lain.",[["وَإِذْ","And when"],["قَالَ","said"],["مُوسَىٰ","Musa"],["لِقَوْمِهِۦ","to his people"],["يَـٰقَوْمِ","O my people"],["ٱذْكُرُوا۟","remember"],["نِعْمَةَ","(the) Favor"],["ٱللَّهِ","(of) Allah"],["عَلَيْكُمْ","upon you"],["إِذْ","when"],["جَعَلَ","He placed"],["فِيكُمْ","among you"],["أَنۢبِيَآءَ","Prophets"],["وَجَعَلَكُم","and made you"],["مُّلُوكًۭا","kings"],["وَءَاتَىٰكُم","and He gave you"],["مَّا","what"],["لَمْ","not"],["يُؤْتِ","He (had) given"],["أَحَدًۭا","(to) anyone"],["مِّنَ","from"],["ٱلْعَـٰلَمِينَ","the worlds"]]],"690":["(Hai kaumku! Masuklah kamu ke tanah suci) yang disucikan (yang telah ditetapkan Allah bagi kamu) telah dititahkan-Nya untuk memasukinya yaitu tanah Syam (dan janganlah kamu lari ke belakang) berbalik surut karena takut kepada musuh (nanti kamu menjadi orang-orang yang merugi.\") dalam usahamu.",[["يَـٰقَوْمِ","O my people"],["ٱدْخُلُوا۟","Enter"],["ٱلْأَرْضَ","the land"],["ٱلْمُقَدَّسَةَ","the Holy"],["ٱلَّتِى","which"],["كَتَبَ","(has been) ordained"],["ٱللَّهُ","(by) Allah"],["لَكُمْ","for you"],["وَلَا","and (do) not"],["تَرْتَدُّوا۟","turn"],["عَلَىٰٓ","on"],["أَدْبَارِكُمْ","your backs"],["فَتَنقَلِبُوا۟","then you will turn back"],["خَـٰسِرِينَ","(as) losers"]]],"691":["(Jawab mereka, \"Hai Musa! Sesungguhnya di dalamnya ada orang-orang yang aniaya) sisa-sisa bangsa Ad yang bertubuh tinggi dan bertenaga besar (Dan sesungguhnya kami tidak akan memasukinya hingga mereka keluar daripadanya. Jika mereka telah keluar daripadanya barulah kami memasuki.\")nya.",[["قَالُوا۟","They said"],["يَـٰمُوسَىٰٓ","O Musa"],["إِنَّ","Indeed"],["فِيهَا","in it"],["قَوْمًۭا","(are) people"],["جَبَّارِينَ","(of) tyrannical strength"],["وَإِنَّا","and indeed, we"],["لَن","never"],["نَّدْخُلَهَا","will enter it"],["حَتَّىٰ","until"],["يَخْرُجُوا۟","they leave"],["مِنْهَا","from it"],["فَإِن","and if"],["يَخْرُجُوا۟","they leave"],["مِنْهَا","[from] it"],["فَإِنَّا","then certainly we (will)"],["دَٰخِلُونَ","enter (it)"]]],"692":["(Berkatalah) kepada mereka (dua orang laki-laki di antara orang-orang yang takut) menyalahi perintah-perintah Allah bernama Yusya dan Kalib, yakni dua orang di antara para pemimpin yang dikirim Musa untuk menyelidiki orang-orang aniaya itu (dan Allah telah memberi kedua mereka itu nikmat) berupa tindakan bijaksana hingga mereka tak hendak menyingkapkan keadaan sebenarnya dari orang-orang aniaya itu selain kepada Musa berbeda halnya dengan anggota-anggota lainnya yang menyiarkan berita itu hingga kaum Musa pun menjadi takut karenanya. (\"Serbulah mereka dengan melalui pintu gerbang) maksudnya pintu gerbang kota dan janganlah takut kepada mereka karena mereka itu tinggal tubuh tanpa hati atau keberanian. (Apabila kamu memasukinya niscaya kamu akan beroleh kemenangan) hal itu mereka ucapkan karena yakin akan beroleh pertolongan Allah dan bahwa Allah pasti menepati janji-Nya. (Dan kepada Allahlah hendaknya kamu bertawakal jika kamu betul-betul orang-orang yang beriman.\")",[["قَالَ","Said"],["رَجُلَانِ","two men"],["مِنَ","from"],["ٱلَّذِينَ","those who"],["يَخَافُونَ","feared (Allah)"],["أَنْعَمَ","(had) favored"],["ٱللَّهُ","Allah"],["عَلَيْهِمَا","[on] both of them"],["ٱدْخُلُوا۟","Enter"],["عَلَيْهِمُ","upon them"],["ٱلْبَابَ","(through) the gate"],["فَإِذَا","then when"],["دَخَلْتُمُوهُ","you have entered it"],["فَإِنَّكُمْ","then indeed, you (will be)"],["غَـٰلِبُونَ ۚ","victorious"],["وَعَلَى","And upon"],["ٱللَّهِ","Allah"],["فَتَوَكَّلُوٓا۟","then put your trust"],["إِن","if"],["كُنتُم","you are"],["مُّؤْمِنِينَ","believers"]]],"693":["(Kata mereka, \"Hai Musa! Kami sekali-kali tidak akan memasukinya untuk selama-lamanya selagi mereka masih berada di dalamnya. Maka pergilah kamu bersama Tuhanmu dan perangilah) mereka (biarlah kami di sini duduk menanti saja.\") tak ikut berperang.",[["قَالُوا۟","They said"],["يَـٰمُوسَىٰٓ","O Musa"],["إِنَّا","Indeed, we"],["لَن","never"],["نَّدْخُلَهَآ","will enter it"],["أَبَدًۭا","ever"],["مَّا","for"],["دَامُوا۟","as long as they are"],["فِيهَا ۖ","in it"],["فَٱذْهَبْ","So go"],["أَنتَ","you"],["وَرَبُّكَ","and your Lord"],["فَقَـٰتِلَآ","and you both fight"],["إِنَّا","Indeed, we"],["هَـٰهُنَا","are [here]"],["قَـٰعِدُونَ","sitting"]]],"694":["(Kata Musa) ketika itu (\"Wahai Tuhanku! Aku tidak menguasai kecuali diriku dan) kecuali (saudaraku) adapun yang lainnya tidak, oleh sebab itu paksalah mereka supaya tunduk (maka pisahkanlah) atau ceraikan (di antara kami dengan orang-orang yang fasik itu.\")",[["قَالَ","He said"],["رَبِّ","O my Lord"],["إِنِّى","Indeed, I"],["لَآ","(do) not"],["أَمْلِكُ","(have) power"],["إِلَّا","except"],["نَفْسِى","(over) myself"],["وَأَخِى ۖ","and my brother"],["فَٱفْرُقْ","so (make a) separation"],["بَيْنَنَا","between us"],["وَبَيْنَ","and between"],["ٱلْقَوْمِ","the people"],["ٱلْفَـٰسِقِينَ","(the) defiantly disobedient"]]],"695":["(Firman Allah) Taala kepadanya (\"Maka kalau begitu negeri itu) yakni tanah suci tadi (diharamkan atas mereka) memasukinya (selama 40 tahun mereka akan bertualang tak tahu jalan) kebingungan (di negeri itu) menurut Ibnu Abbas luasnya sembilan farsakh persegi. (Maka janganlah kamu bersedih) berduka-cita (terhadap kaum yang fasik itu) menurut riwayat mereka memulai perjalanan di waktu malam dengan penuh kesungguhan ke arah yang dituju tetapi di waktu pagi mereka telah berada kembali di tempat semula. Demikian pula halnya perjalanan di waktu siang hingga akhirnya mereka binasa (mati\") kecuali orang-orang yang di waktu itu usianya belum lagi mencapai 20 tahun. Ada yang mengatakan bahwa jumlah mereka enam ratus ribu orang dan di padang itulah, yakni yang disebut padang Tih, wafat Harun dan Musa. Hal itu menjadi rahmat bagi mereka berdua sebaliknya menjadi azab dan siksa bagi umat mereka. Setelah dekat kematiannya, Musa memohon kepada Allah agar didekatkan kepada tanah suci itu kira-kira dalam jarak sepelemparan batu, maka permohonan itu dikabulkannya sebagaimana tersebut dalam hadis. Setelah masa empat puluh tahun itu Allah mengangkat Yusya menjadi nabi dan memerintahkannya untuk memerangi orang-orang aniaya tadi. Maka berangkatlah ia dengan sisa-sisa Israel dan memerangi musuh yang ketika itu ialah hari Jumat. Menurut berita, matahari terhenti selama sesaat menunggu selesai mereka berperang. Diriwayatkan oleh Ahmad dalam musnadnya sebuah hadis bahwa matahari itu tidak pernah tertahan jalannya untuk kepentingan manusia kecuali bagi Yusya, yaitu di malam-malam perjalanannya menuju Baitulmakdis.",[["قَالَ","(Allah) said"],["فَإِنَّهَا","Then indeed it"],["مُحَرَّمَةٌ","(will be) forbidden"],["عَلَيْهِمْ ۛ","to them"],["أَرْبَعِينَ","(for) forty"],["سَنَةًۭ ۛ","years"],["يَتِيهُونَ","they will wander"],["فِى","in"],["ٱلْأَرْضِ ۚ","the earth"],["فَلَا","So (do) not"],["تَأْسَ","grieve"],["عَلَى","over"],["ٱلْقَوْمِ","the people"],["ٱلْفَـٰسِقِينَ","the defiantly disobedient"]]],"696":["(Dan bacakanlah) hai Muhammad (kepada mereka) yakni kepada kaummu (kabar) berita (dua orang anak Adam) yaitu Habil dan Qabil (dengan sebenarnya) berhubungan dengan utlu (ketika keduanya mempersembahkan kurban) kepada Allah berupa domba dari Habil dan hasil tanaman dari Qabil. (Maka diterima dari salah seorang mereka) yakni dari Habil dengan alamat turunnya api dari langit yang melahap kurbannya (dan tidak diterima dari yang lain) yakni dari Qabil yang menjadi murka dan memendam kedengkian dalam dirinya menunggu naik hajinya Adam. (Katanya) yakni Qabil kepada Habil (\"Sungguh, akan kubunuh kamu!\") Kenapa kurbanmu diterima sedangkan kurban saya tidak! (Jawabnya, yakni Habil, \"Sesungguhnya Allah hanya menerima kurban dari orang-orang yang bertakwa\").",[["۞ وَٱتْلُ","And recite"],["عَلَيْهِمْ","to them"],["نَبَأَ","the story"],["ٱبْنَىْ","(of) two sons"],["ءَادَمَ","(of) Adam"],["بِٱلْحَقِّ","in truth"],["إِذْ","when"],["قَرَّبَا","both offered"],["قُرْبَانًۭا","a sacrifice"],["فَتُقُبِّلَ","and it was accepted"],["مِنْ","from"],["أَحَدِهِمَا","one of them"],["وَلَمْ","and not"],["يُتَقَبَّلْ","was accepted"],["مِنَ","from"],["ٱلْـَٔاخَرِ","the other"],["قَالَ","Said (the latter)"],["لَأَقْتُلَنَّكَ ۖ","Surely I will kill you"],["قَالَ","Said (the former)"],["إِنَّمَا","Only"],["يَتَقَبَّلُ","accepts"],["ٱللَّهُ","(does) Allah"],["مِنَ","from"],["ٱلْمُتَّقِينَ","the God fearing"]]],"697":["(\"Sungguh, jika) lam menunjukkan sumpah (kamu mengulurkan) atau menggerakkan (tanganmu kepadaku untuk membunuhku, tidaklah aku akan mengulurkan tanganku kepadamu untuk membunuhmu. Sesungguhnya aku takut akan Allah, Tuhan seru sekalian alam.\") jika membunuhmu.",[["لَئِنۢ","If"],["بَسَطتَ","you stretch"],["إِلَىَّ","towards me"],["يَدَكَ","your hand"],["لِتَقْتُلَنِى","to kill me"],["مَآ","not"],["أَنَا۠","will I"],["بِبَاسِطٍۢ","stretch"],["يَدِىَ","my hand"],["إِلَيْكَ","towards you"],["لِأَقْتُلَكَ ۖ","to kill you"],["إِنِّىٓ","indeed I"],["أَخَافُ","fear"],["ٱللَّهَ","Allah"],["رَبَّ","(the) Lord"],["ٱلْعَـٰلَمِينَ","(of) the worlds"]]],"698":["(Sesungguhnya aku ingin agar kamu kembali membawa dosaku) maksudnya kembali menghadap kepada Allah dengan membawa dosa membunuhku (dan dosamu sendiri) yakni yang kamu perbuat sebelumnya (hingga kamu akan menjadi penghuni neraka) sedangkan aku tak ingin memikul dosamu jika membunuhnya sehingga aku menjadi penghuni neraka pula. Firman Allah swt.: (\"Dan demikianlah balasan bagi orang-orang yang aniaya.\")",[["إِنِّىٓ","Indeed, I"],["أُرِيدُ","wish"],["أَن","that"],["تَبُوٓأَ","you be laden"],["بِإِثْمِى","with my sin"],["وَإِثْمِكَ","and your sin"],["فَتَكُونَ","so you will be"],["مِنْ","among"],["أَصْحَـٰبِ","(the) companions"],["ٱلنَّارِ ۚ","(of) the Fire"],["وَذَٰلِكَ","and that"],["جَزَٰٓؤُا۟","(is the) recompense"],["ٱلظَّـٰلِمِينَ","(of) the wrong-doers"]]],"699":["(Tetapi nafsunya menggodanya untuk membunuh saudaranya lalu dibunuhnyalah, maka jadilah dia termasuk di antara orang-orang yang merugi) disebabkan pembunuhan itu. Mulanya ia tidak tahu apa yang akan diperbuatnya terhadap mayat saudaranya itu karena ia adalah mayat yang pertama dari anak cucu Adam di muka bumi, maka dipikulnyalah di atas punggungnya.",[["فَطَوَّعَتْ","Then prompted"],["لَهُۥ","to him"],["نَفْسُهُۥ","his soul"],["قَتْلَ","(to) kill"],["أَخِيهِ","his brother"],["فَقَتَلَهُۥ","so he killed him"],["فَأَصْبَحَ","and became"],["مِنَ","of"],["ٱلْخَـٰسِرِينَ","the losers"]]],"700":["(Lalu Allah mengirimkan seekor burung gagak menggali bumi) maksudnya mengorek tanah dengan paruh dan kedua kakinya lalu menimbunkannya di atas bangkai saudaranya seakan-akan menguburkannya (untuk memperlihatkan kepadanya bagaimana seharusnya dia menutupi) atau menguburkan (mayat saudaranya. Katanya, \"Wahai celakanya daku! Mengapa aku tidak mampu) buat (bertindak seperti burung gagak ini hingga dapat menguburkan mayat saudaraku. Maka jadilah dia di antara orang-orang yang menyesal.\") karena telah memikulnya tadi. Kemudian digalinya liang lalu dikuburkannya mayat saudaranya Habil itu.",[["فَبَعَثَ","Then (was) sent"],["ٱللَّهُ","(by) Allah"],["غُرَابًۭا","a crow"],["يَبْحَثُ","it (was) scratching"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["لِيُرِيَهُۥ","to show him"],["كَيْفَ","how"],["يُوَٰرِى","to hide"],["سَوْءَةَ","(the) dead body"],["أَخِيهِ ۚ","(of) his brother"],["قَالَ","He said"],["يَـٰوَيْلَتَىٰٓ","Woe to me"],["أَعَجَزْتُ","Am I unable"],["أَنْ","that"],["أَكُونَ","I can be"],["مِثْلَ","like"],["هَـٰذَا","this"],["ٱلْغُرَابِ","[the] crow"],["فَأُوَٰرِىَ","and hide"],["سَوْءَةَ","(the) dead body"],["أَخِى ۖ","(of) my brother"],["فَأَصْبَحَ","Then he became"],["مِنَ","of"],["ٱلنَّـٰدِمِينَ","the regretful"]]],"701":["(Oleh sebab itu) artinya karena perbuatan Qabil itu tadi (Kami tetapkan bagi Bani Israel bahwa sesungguhnya) innahuu disebut dhamir sya`n (siapa yang membunuh seorang manusia bukan karena manusia lainnya) yang dibunuhnya (atau) bukan karena (kerusakan) yang diperbuatnya (di muka bumi) berupa kekafiran, perzinaan atau perampokan dan sebagainya (maka seolah-olah dia telah membunuh manusia kesemuanya. Sebaliknya siapa yang memelihara kehidupannya) artinya tidak hendak membunuhnya (maka seolah-olah ia telah memelihara kehidupan manusia seluruhnya.) Kata Ibnu Abbas, \"Ini dilihat dari segi melanggar kesuciannya dan dari segi memelihara serta menjaganya.\" (dan sesungguhnya telah datang kepada mereka itu) yakni kepada orang-orang Israel (rasul-rasul Kami membawa keterangan-keterangan yang jelas) maksudnya mukjizat-mukjizat (kemudian banyak di antara mereka sesudah itu melampaui batas dalam berbuat kerusakan di muka bumi) dengan kekafiran, melakukan pembunuhan dan lain-lain.",[["مِنْ","From"],["أَجْلِ","time"],["ذَٰلِكَ","that"],["كَتَبْنَا","We ordained"],["عَلَىٰ","on"],["بَنِىٓ","(the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"],["أَنَّهُۥ","that he"],["مَن","who"],["قَتَلَ","kills"],["نَفْسًۢا","a soul"],["بِغَيْرِ","other than"],["نَفْسٍ","(for) a soul"],["أَوْ","or"],["فَسَادٍۢ","(for) spreading corruption"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["فَكَأَنَّمَا","then (it) is as if"],["قَتَلَ","he has killed"],["ٱلنَّاسَ","mankind"],["جَمِيعًۭا","all"],["وَمَنْ","and whoever"],["أَحْيَاهَا","saves it"],["فَكَأَنَّمَآ","then (it) is as if"],["أَحْيَا","he has saved"],["ٱلنَّاسَ","mankind"],["جَمِيعًۭا ۚ","all"],["وَلَقَدْ","And surely"],["جَآءَتْهُمْ","came to them"],["رُسُلُنَا","Our Messengers"],["بِٱلْبَيِّنَـٰتِ","with clear Signs"],["ثُمَّ","yet"],["إِنَّ","indeed"],["كَثِيرًۭا","many"],["مِّنْهُم","of them"],["بَعْدَ","after"],["ذَٰلِكَ","that"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["لَمُسْرِفُونَ","(are) surely those who commit excesses"]]],"702":["(Bahwasanya pembalasan terhadap orang-orang yang memerangi Allah dan rasul-Nya) artinya dengan memerangi kaum muslimin (dan membuat kerusakan di muka bumi) dengan menyamun dan merampok (ialah dengan membunuh atau menyalib mereka atau tangan dan kaki mereka dipotong secara timbal balik) maksudnya tangan kanan dengan kaki kiri mereka (atau dibuang dari kampung halamannya). Atau secara bertingkat, maka hukum bunuh itu ialah bagi yang membunuh saja, hukum salib bagi yang membunuh dan merampas harta, hukum potong bagi yang merampas harta tetapi tanpa membunuh sedangkan hukum buang bagi yang mengacau saja. Hal ini dikemukakan oleh Ibnu Abbas dan dianut oleh Syafii. Menurut yang terkuat di antara dua buah pendapat dilaksanakannya hukum salib itu ialah tiga hari setelah dihukum bunuh. Tetapi ada pula yang mengatakan tidak lama sebelum dibunuh. Termasuk dalam hukum buang hukuman lain yang sama pengaruhnya dalam memberikan pelajaran seperti tahanan penjara dan lain-lain. (Demikian itu) maksudnya pembalasan atau hukuman tersebut (merupakan kehinaan bagi mereka) kenistaan (di dunia sedangkan di akhirat mereka beroleh siksa yang besar) yaitu siksa neraka.",[["إِنَّمَا","Only"],["جَزَٰٓؤُا۟","(the) recompense"],["ٱلَّذِينَ","(for) those who"],["يُحَارِبُونَ","wage war"],["ٱللَّهَ","(against) Allah"],["وَرَسُولَهُۥ","and His Messenger"],["وَيَسْعَوْنَ","and strive"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["فَسَادًا","spreading corruption"],["أَن","(is) that"],["يُقَتَّلُوٓا۟","they be killed"],["أَوْ","or"],["يُصَلَّبُوٓا۟","they be crucified"],["أَوْ","or"],["تُقَطَّعَ","be cut off"],["أَيْدِيهِمْ","their hands"],["وَأَرْجُلُهُم","and their feet"],["مِّنْ","of"],["خِلَـٰفٍ","opposite sides"],["أَوْ","or"],["يُنفَوْا۟","they be exiled"],["مِنَ","from"],["ٱلْأَرْضِ ۚ","the land"],["ذَٰلِكَ","That"],["لَهُمْ","(is) for them"],["خِزْىٌۭ","disgrace"],["فِى","in"],["ٱلدُّنْيَا ۖ","the world"],["وَلَهُمْ","and for them"],["فِى","in"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["عَذَابٌ","(is) a punishment"],["عَظِيمٌ","great"]]],"703":["(Kecuali orang-orang yang tobat) di antara orang-orang yang menyalakan api dan peperangan perampokan tadi (sebelum kamu dapat menguasai mereka, maka ketahuilah bahwa Allah Maha Pengampun) terhadap mereka atas perbuatan mereka itu (lagi Maha Penyayang) kepada mereka. Dalam ayat ini tidak disebutkan \"janganlah mereka kamu jatuhi hukuman\" untuk menunjukkan bahwa dengan bertobat itu yang gugur hanyalah hak Allah dan tidak hak manusia. Demikian yang dapat ditangkap dengan jelas dan saya lihat tidak seorang pun yang menentangnya, wallahu a`lam. Maka jika seseorang membunuh dan merampas harta, maka ia dihukum bunuh dan dipotong tetapi tidak disalib. Ini merupakan yang terkuat di antara kedua pendapat Syafii. Mengenai bertobat setelah ia dapat ditangkap, maka tak ada pengaruh dan manfaat apa-apa. Ini juga merupakan yang terkuat di antara kedua pendapat Imam Syafii.",[["إِلَّا","Except"],["ٱلَّذِينَ","those who"],["تَابُوا۟","repent"],["مِن","from"],["قَبْلِ","before"],["أَن","that"],["تَقْدِرُوا۟","you overpower"],["عَلَيْهِمْ ۖ","[over] them"],["فَٱعْلَمُوٓا۟","then know"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"704":["(Hai orang-orang yang beriman, bertakwalah kamu kepada Allah) artinya takutlah akan siksa-Nya dengan jalan menaati-Nya (dan carilah jalan kepada-Nya) yaitu jalan yang akan mendekatkan dirimu kepada-Nya dengan jalan taat dan ibadah (dan berjihadlah pada jalan-Nya) maksudnya untuk meninggikan agama-Nya (semoga kamu beruntung atau beroleh keberhasilan).",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["ٱتَّقُوا۟","Fear"],["ٱللَّهَ","Allah"],["وَٱبْتَغُوٓا۟","and seek"],["إِلَيْهِ","towards Him"],["ٱلْوَسِيلَةَ","the means"],["وَجَـٰهِدُوا۟","and strive hard"],["فِى","in"],["سَبِيلِهِۦ","His way"],["لَعَلَّكُمْ","so that you may"],["تُفْلِحُونَ","succeed"]]],"705":["(Sesungguhnya orang-orang kafir, sekiranya) terjadilah (bahwa mereka memiliki seluruh yang terdapat di bumi dan sebanyak itu lagi sebagai tambahannya untuk menebus diri mereka dari siksa hari kiamat tidaklah akan diterima dari mereka dan bagi mereka azab yang pedih).",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieve"],["لَوْ","if"],["أَنَّ","that"],["لَهُم","for them"],["مَّا","(is) what"],["فِى","(is) in"],["ٱلْأَرْضِ","the earth"],["جَمِيعًۭا","all"],["وَمِثْلَهُۥ","and the like of it"],["مَعَهُۥ","with it"],["لِيَفْتَدُوا۟","to ransom themselves"],["بِهِۦ","with it"],["مِنْ","from"],["عَذَابِ","(the) punishment"],["يَوْمِ","(of the) Day"],["ٱلْقِيَـٰمَةِ","(of) the Resurrection"],["مَا","not"],["تُقُبِّلَ","will be accepted"],["مِنْهُمْ ۖ","from them"],["وَلَهُمْ","and for them"],["عَذَابٌ","(is) a punishment"],["أَلِيمٌۭ","painful"]]],"706":["(Mereka ingin) mengangankan (hendak keluar dari neraka, tetapi tidak mungkin keluar daripadanya dan bagi mereka siksa yang kekal) untuk selama-lamanya.",[["يُرِيدُونَ","They will wish"],["أَن","that"],["يَخْرُجُوا۟","they come out"],["مِنَ","of"],["ٱلنَّارِ","the Fire"],["وَمَا","but not"],["هُم","they"],["بِخَـٰرِجِينَ","will come out"],["مِنْهَا ۖ","of it"],["وَلَهُمْ","And for them"],["عَذَابٌۭ","(is) a punishment"],["مُّقِيمٌۭ","lasting"]]],"707":["(Laki-laki yang mencuri dan wanita yang mencuri) al yang terdapat pada keduanya menunjukkannya sebagai isim maushul dan berfungsi sebagai mubtada, mengingat al mirip dengan syarat maka khabarnya diawali dengan fa, yaitu (maka potonglah tangan mereka) tangan kanan masing-masing mulai dari pergelangan. Dinyatakan oleh sunah bahwa hukum potong itu dilaksanakan jika yang dicuri itu bernilai seperempat dinar atau lebih; jika perbuatannya itu diulanginya lagi maka yang dipotong kakinya yang kiri dari pergelangan kaki, kemudian tangan kiri lalu kaki kanan dan setelah itu dilakukan hukum takzir (sebagai balasan) manshub sebagai mashdar (atas apa yang mereka kerjakan dan sebagai siksaan) artinya hukuman bagi mereka (dari Allah dan Allah Maha Perkasa) artinya menguasai segala urusan (lagi Maha Bijaksana) terhadap makhluk-Nya.",[["وَٱلسَّارِقُ","And (for) the male thief"],["وَٱلسَّارِقَةُ","and the female thief "],["فَٱقْطَعُوٓا۟","[then] cut off"],["أَيْدِيَهُمَا","their hands"],["جَزَآءًۢ","(as) a recompense"],["بِمَا","for what"],["كَسَبَا","they earned"],["نَكَـٰلًۭا","(as) an exemplary (punishment)"],["مِّنَ","from"],["ٱللَّهِ ۗ","Allah"],["وَٱللَّهُ","And Allah"],["عَزِيزٌ","(is) All-Mighty"],["حَكِيمٌۭ","All-Wise"]]],"708":["(Siapa yang tobat setelah keaniayaannya) artinya tidak mencuri lagi (dan memperbaiki diri) atau amalnya (maka sesungguhnya Allah menerima tobatnya. Sesungguhnya Allah itu Maha Pengampun lagi Maha Penyayang) untuk menguraikan ini telah kita kemukakan keterangan yang lalu. Maka dengan tobatnya itu tidaklah gugur hak manusia berupa hukum potong dan pengembalian harta. Kemudian sunah menyatakan bahwa jika yang punya hak memberi maaf sebelum diadukan kepada imam, gugurlah hukum potong itu terhadapnya. Dan inilah yang menjadi pendapat Syafii.",[["فَمَن","But whoever"],["تَابَ","repented"],["مِنۢ","from"],["بَعْدِ","after"],["ظُلْمِهِۦ","his wrongdoing"],["وَأَصْلَحَ","and reforms"],["فَإِنَّ","then indeed"],["ٱللَّهَ","Allah"],["يَتُوبُ","will turn in forgiveness"],["عَلَيْهِ ۗ","to him"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌ","Most Merciful"]]],"709":["(Tidaklah kamu ketahui) pertanyaan ini sebagai pengukuhan (bahwa sesungguhnya Allah memiliki kerajaan langit dan bumi, disiksa-Nya siapa yang dikehendaki-Nya) untuk disiksa (dan diampuni-Nya siapa yang dikehendaki-Nya) untuk diampuni. (Dan Allah Maha Kuasa atas segala sesuatu) di antaranya menurunkan siksa atau memberi ampun.",[["أَلَمْ","Do not"],["تَعْلَمْ","you know"],["أَنَّ","that"],["ٱللَّهَ","Allah"],["لَهُۥ","to Him (belongs)"],["مُلْكُ","(the) dominion"],["ٱلسَّمَـٰوَٰتِ","(of) the heavens"],["وَٱلْأَرْضِ","and the earth"],["يُعَذِّبُ","He punishes"],["مَن","whom"],["يَشَآءُ","He wills"],["وَيَغْفِرُ","and He forgives"],["لِمَن","[to] whom"],["يَشَآءُ ۗ","He wills"],["وَٱللَّهُ","And Allah"],["عَلَىٰ","(is) on"],["كُلِّ","every"],["شَىْءٍۢ","thing"],["قَدِيرٌۭ","All-Powerful"]]],"710":["(Hai Rasul, janganlah kamu menjadi bersedih hati oleh) disebabkan perbuatan (orang-orang yang berlomba-lomba dalam kekafiran) hingga tanpa menunggu lama mereka akan terjatuh di dalamnya; artinya bila ada kesempatan mereka akan menyatakan kekafiran itu (di antara) min merupakan penjelasan (orang-orang yang mengatakan dengan mulut mereka, \"Kami telah beriman.\") maksudnya dengan lidah mereka nyatakan hal tersebut (padahal hati mereka tidak beriman) mereka ini ialah orang-orang munafik (dan juga di antara orang-orang Yahudi) yakni suatu kaum (yang amat gemar mendengar berita-berita bohong) yang dibuat-buat oleh pendeta-pendeta mereka lalu mereka terima dengan baik (dan amat suka pula mendengar berita-berita) daripadamu (untuk suatu kaum) artinya demi kepentingan kaum (yang lain) dari golongan Yahudi (yang belum pernah datang kepadamu) yakni warga Khaibar. Terdapat di sana sepasang laki-laki dan perempuan yang telah berumah tangga melakukan perzinaan, tetapi mereka berkeberatan untuk menjalankan hukuman rajam kepada kedua pesakitan. Lalu mereka mengirimkan orang-orang warga Quraizhah untuk menanyakan hukuman mereka itu kepada Nabi Muhammad saw. (Mereka mengubah-ubah perkataan) yang tercantum dalam Taurat seperti ayat tentang rajam (dari tempat-tempatnya) yang ditaruh Allah padanya; artinya mereka menggantikannya dengan yang lain. (Kata mereka) yakni kepada orang-orang yang mereka utus tadi (\"Jika yang diberikan kepadamu itu ialah ini) maksudnya hukum yang telah dirubah dan difatwakan oleh Muhammad yaitu hukum pukulan (maka ambillah) terimalah (tetapi jika bukan itu yang diberikan kepadamu) dan fatwa yang diberikannya bertentangan dengannya (maka berhati-hatilah.\") untuk menerimanya. (Siapa yang dikehendaki Allah kesesatannya, maka kamu sekali-kali tidak akan dapat menguasai sesuatu yang datang dari Allah) untuk menolaknya (mereka itu ialah orang-orang yang tidak dikehendaki Allah menyucikan hati mereka) dari kekafiran, dan sekiranya dikehendaki-Nya tentulah hal itu akan tercapai. (Bagi mereka di dunia ini kehinaan) kenistaan dengan terbukanya rahasia dan pembayaran upeti (sedangkan di akhirat siksa yang besar.)",[["۞ يَـٰٓأَيُّهَا","O"],["ٱلرَّسُولُ","Messenger"],["لَا","Let not"],["يَحْزُنكَ","grieve you"],["ٱلَّذِينَ","those who"],["يُسَـٰرِعُونَ","hasten"],["فِى","in (to)"],["ٱلْكُفْرِ","[the] disbelief "],["مِنَ","of"],["ٱلَّذِينَ","those who"],["قَالُوٓا۟","said"],["ءَامَنَّا","We believe"],["بِأَفْوَٰهِهِمْ","with their mouths"],["وَلَمْ","and not"],["تُؤْمِن","believe"],["قُلُوبُهُمْ ۛ","their hearts"],["وَمِنَ","and from"],["ٱلَّذِينَ","those who"],["هَادُوا۟ ۛ","(are) Jews"],["سَمَّـٰعُونَ","They (are) listeners"],["لِلْكَذِبِ","to falsehood"],["سَمَّـٰعُونَ","(and) listeners"],["لِقَوْمٍ","for people"],["ءَاخَرِينَ","other"],["لَمْ","(who have) not"],["يَأْتُوكَ ۖ","come to you"],["يُحَرِّفُونَ","They distort"],["ٱلْكَلِمَ","the words"],["مِنۢ","from"],["بَعْدِ","after"],["مَوَاضِعِهِۦ ۖ","their context"],["يَقُولُونَ","saying"],["إِنْ","If"],["أُوتِيتُمْ","you are given"],["هَـٰذَا","this"],["فَخُذُوهُ","[so] take it"],["وَإِن","but if"],["لَّمْ","not"],["تُؤْتَوْهُ","you are given it"],["فَٱحْذَرُوا۟ ۚ","then beware"],["وَمَن","And (for) whom"],["يُرِدِ","intends"],["ٱللَّهُ","Allah"],["فِتْنَتَهُۥ","his trial"],["فَلَن","then never"],["تَمْلِكَ","will you have power"],["لَهُۥ","for him"],["مِنَ","against"],["ٱللَّهِ","Allah"],["شَيْـًٔا ۚ","anything"],["أُو۟لَـٰٓئِكَ","Those"],["ٱلَّذِينَ","(are) the ones"],["لَمْ","never"],["يُرِدِ","will intend"],["ٱللَّهُ","Allah"],["أَن","that"],["يُطَهِّرَ","He purifies"],["قُلُوبَهُمْ ۚ","their hearts"],["لَهُمْ","For them"],["فِى","in"],["ٱلدُّنْيَا","the world"],["خِزْىٌۭ ۖ","(is) disgrace"],["وَلَهُمْ","and for them"],["فِى","in"],["ٱلْـَٔاخِرَةِ","the Hereafter"],["عَذَابٌ","(is) a punishment"],["عَظِيمٌۭ","great"]]],"711":["(Mereka orang-orang yang gemar mendengar berita-berita bohong dan banyak memakan yang haram) dibaca suht atau suhut; artinya barang haram seperti uang suap (maka jika mereka datang kepadamu) untuk meminta sesuatu keputusan (maka putuskanlah di antara mereka atau berpalinglah dari mereka) pilihan di antara alternatif ini dihapus/dinasakh dengan firman-Nya, \"..... maka putuskanlah di antara mereka.\" Oleh sebab itu jika mereka mengadukan hal itu kepada kita wajiblah kita memberikan keputusannya di antara mereka. Dan ini merupakan yang terkuat di antara kedua pendapat Syafii. Dan sekiranya mereka mengadukan perkara itu bersama orang Islam, maka hukum memutuskan itu wajib secara ijmak. (Jika mereka berpaling daripadamu, maka sekali-kali tidak akan memberi mudarat kepadamu sedikit pun juga. Dan jika kamu memutuskan) perkara di antara mereka (maka putuskanlah di antara mereka dengan adil) tidak berat sebelah. (Sesungguhnya Allah menyukai orang-orang yang adil) dalam memberikan keputusan dan akan memberi mereka pahala.",[["سَمَّـٰعُونَ","Listeners"],["لِلْكَذِبِ","to [the] falsehood"],["أَكَّـٰلُونَ","devourers"],["لِلسُّحْتِ ۚ","of the forbidden"],["فَإِن","So if"],["جَآءُوكَ","they come to you"],["فَٱحْكُم","then judge"],["بَيْنَهُمْ","between them"],["أَوْ","or"],["أَعْرِضْ","turn away"],["عَنْهُمْ ۖ","from them"],["وَإِن","And if"],["تُعْرِضْ","you turn away"],["عَنْهُمْ","from them"],["فَلَن","then never"],["يَضُرُّوكَ","will they harm you"],["شَيْـًۭٔا ۖ","(in) anything"],["وَإِنْ","And if"],["حَكَمْتَ","you judge"],["فَٱحْكُم","then judge"],["بَيْنَهُم","between them"],["بِٱلْقِسْطِ ۚ","with [the] justice"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["يُحِبُّ","loves"],["ٱلْمُقْسِطِينَ","the ones who are just"]]],"712":["(Dan betapa caranya mereka mengangkatmu menjadi hakim mereka padahal di sisi mereka ada Taurat yang memuat hukum Allah) yaitu dengan rajam. Pertanyaan ini menunjukkan keheranan; artinya maksud mereka yang sebenarnya bukanlah untuk mengetahui kebenaran tetapi untuk mencari mana yang lebih ringan (Kemudian mereka berpaling) dari hukum rajammu yang sebenarnya sesuai dengan kitab mereka (setelah demikian itu) setelah diberi keputusan itu (dan tidaklah mereka orang-orang yang sungguh-sungguh beriman.)",[["وَكَيْفَ","But how can"],["يُحَكِّمُونَكَ","they appoint you a judge"],["وَعِندَهُمُ","while they (have) with them"],["ٱلتَّوْرَىٰةُ","the Taurat"],["فِيهَا","in it"],["حُكْمُ","(is the) Command"],["ٱللَّهِ","(of) Allah"],["ثُمَّ","Then"],["يَتَوَلَّوْنَ","they turn away"],["مِنۢ","from"],["بَعْدِ","after"],["ذَٰلِكَ ۚ","that"],["وَمَآ","and not"],["أُو۟لَـٰٓئِكَ","those"],["بِٱلْمُؤْمِنِينَ","(are) the believers"]]],"713":["(Sesungguhnya Kami telah menurunkan Taurat berisi petunjuk) dari kesesatan (dan cahaya) untuk menjelaskan hukum-hukum (yang diambil untuk memutuskan hukum oleh nabi-nabi) dari Bani Israel (yang tunduk) menyerahkan diri kepada Allah (bagi orang-orang Yahudi dan oleh orang-orang alim dan para pendeta) yakni ahli-ahli hukum dari kalangan mereka (dengan apa) disebabkan karena (mereka diminta untuk menyimpan) artinya diberi amanat untuk menjaga oleh Allah (Kitabullah) jangan sampai diubah-ubah (dan mereka menjadi saksi terhadapnya) bahwa ia benar adanya. (Maka janganlah kamu takut akan manusia) hai orang-orang Yahudi dalam menyingkapkan sifat-sifat dan ciri-ciri Muhammad saw. yang kamu ketahui, tentang ayat rajam dan sebagainya (hanya takutlah kepada-Ku) dalam menyembunyikannya (dan janganlah kamu beli, maksudnya, jangan kamu tukar ayat-ayat-Ku dengan harga yang sedikit) berupa harta benda dunia yang kamu dapatkan sebagai imbalan menyembunyikannya. (Siapa yang tidak memutuskan menurut apa yang diturunkan Allah, maka merekalah orang-orang yang kafir) terhadap-Nya.",[["إِنَّآ","Indeed"],["أَنزَلْنَا","We revealed"],["ٱلتَّوْرَىٰةَ","the Taurat"],["فِيهَا","in it"],["هُدًۭى","(was) Guidance"],["وَنُورٌۭ ۚ","and light"],["يَحْكُمُ","judged"],["بِهَا","by it"],["ٱلنَّبِيُّونَ","the Prophets"],["ٱلَّذِينَ","those who"],["أَسْلَمُوا۟","had submitted (to Allah)"],["لِلَّذِينَ","for those who"],["هَادُوا۟","were Jews"],["وَٱلرَّبَّـٰنِيُّونَ","and the Rabbis"],["وَٱلْأَحْبَارُ","and the scholars"],["بِمَا","with what"],["ٱسْتُحْفِظُوا۟","they were entrusted"],["مِن","of"],["كِتَـٰبِ","(the) Book"],["ٱللَّهِ","(of) Allah"],["وَكَانُوا۟","and they were"],["عَلَيْهِ","to it"],["شُهَدَآءَ ۚ","witnesses"],["فَلَا","So (do) not"],["تَخْشَوُا۟","fear"],["ٱلنَّاسَ","the people"],["وَٱخْشَوْنِ","but fear Me"],["وَلَا","and (do) not"],["تَشْتَرُوا۟","sell"],["بِـَٔايَـٰتِى","My Verses"],["ثَمَنًۭا","(for) a price"],["قَلِيلًۭا ۚ","little"],["وَمَن","And whoever"],["لَّمْ","(does) not"],["يَحْكُم","judge"],["بِمَآ","by what"],["أَنزَلَ","has revealed"],["ٱللَّهُ","Allah"],["فَأُو۟لَـٰٓئِكَ","then those"],["هُمُ","[they]"],["ٱلْكَـٰفِرُونَ","(are) the disbelievers"]]],"714":["(Dan telah Kami tetapkan terhadap mereka d dalamnya) maksudnya di dalam Taurat (bahwa jiwa) dibunuh (karena jiwa) yang dibunuhnya (mata) dicongkel (karena mata, hidung) dipancung (karena hidung, telinga) dipotong (karena telinga, gigi) dicabut (karena gigi) menurut satu qiraat dengan marfu'nya keempat anggota tubuh tersebut (dan luka-luka pun) manshub atau marfu' (berlaku kisas) artinya dilaksanakan padanya hukum balas jika mungkin; seperti tangan, kaki, kemaluan dan sebagainya. Hukuman ini walaupun diwajibkan atas mereka tetapi ditaqrirkan atau diakui tetap berlaku dalam syariat kita. (Siapa menyedekahkannya) maksudnya menguasai dirinya dengan melepas hak kisas itu (maka itu menjadi penebus dosanya) atas kesalahannya (dan siapa yang tidak memutuskan dengan apa yang diturunkan Allah) seperti kisas dan lain-lain (merekalah orang-orang yang aniaya).",[["وَكَتَبْنَا","And We ordained"],["عَلَيْهِمْ","for them"],["فِيهَآ","in it"],["أَنَّ","that "],["ٱلنَّفْسَ","the life"],["بِٱلنَّفْسِ","for the life"],["وَٱلْعَيْنَ","and the eye"],["بِٱلْعَيْنِ","for the eye"],["وَٱلْأَنفَ","and the nose"],["بِٱلْأَنفِ","for the nose"],["وَٱلْأُذُنَ","and the ear"],["بِٱلْأُذُنِ","for the ear"],["وَٱلسِّنَّ","and the tooth"],["بِٱلسِّنِّ","for the tooth"],["وَٱلْجُرُوحَ","and (for) wounds"],["قِصَاصٌۭ ۚ","(is) retribution"],["فَمَن","But whoever"],["تَصَدَّقَ","gives charity"],["بِهِۦ","with it"],["فَهُوَ","then it is"],["كَفَّارَةٌۭ","an expiation"],["لَّهُۥ ۚ","for him"],["وَمَن","And whoever"],["لَّمْ","(does) not"],["يَحْكُم","judge"],["بِمَآ","by what"],["أَنزَلَ","has revealed"],["ٱللَّهُ","Allah"],["فَأُو۟لَـٰٓئِكَ","then those"],["هُمُ","[they]"],["ٱلظَّـٰلِمُونَ","(are) the wrongdoers"]]],"715":["(Dan Kami iringi jejak-jejak mereka) maksudnya jejak para nabi itu (dengan Isa putra Maryam, membenarkan apa yang berada di depannya) maksudnya yang sebelumnya (berupa Taurat dan Kami berikan kepadanya Injil yang berisi petunjuk) dari kesesatan (dan cahaya) artinya penjelasan bagi hukum-hukum (serta membenarkan) menjadi hal (bagi kitab Taurat yang berada sebelumnya) membenarkan hukum-hukum Taurat (serta menjadi petunjuk dan pengajaran bagi orang-orang yang takwa).",[["وَقَفَّيْنَا","And We sent"],["عَلَىٰٓ","on"],["ءَاثَـٰرِهِم","their footsteps"],["بِعِيسَى","Isa"],["ٱبْنِ","son"],["مَرْيَمَ","(of) Maryam"],["مُصَدِّقًۭا","confirming"],["لِّمَا","what"],["بَيْنَ","(was) between"],["يَدَيْهِ","his hands"],["مِنَ","of"],["ٱلتَّوْرَىٰةِ ۖ","the Taurat"],["وَءَاتَيْنَـٰهُ","and We gave him"],["ٱلْإِنجِيلَ","the Injeel"],["فِيهِ","in it"],["هُدًۭى","(was) Guidance"],["وَنُورٌۭ","and light"],["وَمُصَدِّقًۭا","and confirming"],["لِّمَا","what"],["بَيْنَ","(was) between"],["يَدَيْهِ","his hands"],["مِنَ","of"],["ٱلتَّوْرَىٰةِ","the Taurat"],["وَهُدًۭى","and a Guidance"],["وَمَوْعِظَةًۭ","and an admonition"],["لِّلْمُتَّقِينَ","for the God conscious"]]],"716":["(Dan pengikut-pengikut Injil hendaklah memutuskan perkara dengan apa yang diturunkan Allah di dalamnya) berupa hukum-hukum dan menurut satu qiraat walyahkum itu dibaca waliyahkum karena diathafkan pada ma`mul aatainaahu (Dan siapa yang tidak memutuskan perkara dengan apa yang diturunkan Allah, maka mereka itu orang-orang yang fasik.)",[["وَلْيَحْكُمْ","And let judge"],["أَهْلُ","(the) People"],["ٱلْإِنجِيلِ","(of) the Injeel"],["بِمَآ","by what"],["أَنزَلَ","has revealed"],["ٱللَّهُ","Allah"],["فِيهِ ۚ","in it"],["وَمَن","And whoever"],["لَّمْ","(does) not"],["يَحْكُم","judge"],["بِمَآ","by what"],["أَنزَلَ","has revealed"],["ٱللَّهُ","Allah"],["فَأُو۟لَـٰٓئِكَ","then those"],["هُمُ","[they] (are)"],["ٱلْفَـٰسِقُونَ","the defiantly disobedient"]]],"717":["(Dan telah Kami turunkan kepadamu) hai Muhammad (kitab) yakni Alquran (dengan kebenaran) berkaitan dengan anzalnaa (membenarkan apa yang terdapat di hadapannya) maksudnya yang sebelumnya (di antara kitab dan menjadi saksi) atau batu ujian (terhadapnya) kitab di sini maksudnya ialah kitab-kitab terdahulu. (Sebab itu putuskanlah perkara mereka) maksudnya antara ahli kitab jika mereka mengadu kepadamu (dengan apa yang diturunkan Allah) kepadamu (dan janganlah kamu mengikuti hawa nafsu mereka) dengan menyimpang (dari kebenaran yang telah datang kepadamu. Bagi tiap-tiap umat di antara kamu Kami beri) hai manusia (aturan dan jalan) maksudnya jalan yang nyata dan agama dan yang akan mereka tempuh. (Sekiranya dikehendaki Allah tentulah kamu dijadikan-Nya satu umat) dengan hanya satu syariat (tetapi) dibagi-bagi-Nya kamu kepada beberapa golongan (untuk mengujimu) mencoba (mengenai apa yang telah diberikan-Nya kepadamu) berupa syariat yang bermacam-macam untuk melihat siapakah di antara kamu yang taat dan siapa pula yang durhaka (maka berlomba-lombalah berbuat kebaikan) berpaculah mengerjakannya. (Hanya kepada Allahlah kembali kamu semua) dengan kebangkitan (maka diberitahukan-Nya kepadamu apa yang kamu perbantahkan itu) yakni mengenai soal agama dan dibalas-Nya setiap kamu menurut amal masing-masing.",[["وَأَنزَلْنَآ","And We revealed"],["إِلَيْكَ","to you"],["ٱلْكِتَـٰبَ","the Book"],["بِٱلْحَقِّ","in [the] truth"],["مُصَدِّقًۭا","confirming"],["لِّمَا","what"],["بَيْنَ","(was) before"],["يَدَيْهِ","his hands"],["مِنَ","of"],["ٱلْكِتَـٰبِ","the Book"],["وَمُهَيْمِنًا","and a guardian"],["عَلَيْهِ ۖ","over it"],["فَٱحْكُم","So judge"],["بَيْنَهُم","between them"],["بِمَآ","by what"],["أَنزَلَ","has revealed"],["ٱللَّهُ ۖ","Allah"],["وَلَا","and (do) not"],["تَتَّبِعْ","follow"],["أَهْوَآءَهُمْ","their vain desires"],["عَمَّا","when"],["جَآءَكَ","has come to you"],["مِنَ","of"],["ٱلْحَقِّ ۚ","the truth"],["لِكُلٍّۢ","For each"],["جَعَلْنَا","We have made"],["مِنكُمْ","for you"],["شِرْعَةًۭ","a law"],["وَمِنْهَاجًۭا ۚ","and a clear way"],["وَلَوْ","And if"],["شَآءَ","(had) willed"],["ٱللَّهُ","Allah"],["لَجَعَلَكُمْ","He (would have) made you"],["أُمَّةًۭ","a community"],["وَٰحِدَةًۭ","one"],["وَلَـٰكِن","[and] but"],["لِّيَبْلُوَكُمْ","to test you"],["فِى","in"],["مَآ","what"],["ءَاتَىٰكُمْ ۖ","He (has) given you"],["فَٱسْتَبِقُوا۟","so race"],["ٱلْخَيْرَٰتِ ۚ","(to) the good"],["إِلَى","To"],["ٱللَّهِ","Allah"],["مَرْجِعُكُمْ","you will return"],["جَمِيعًۭا","all"],["فَيُنَبِّئُكُم","then He will inform you"],["بِمَا","of what"],["كُنتُمْ","you were"],["فِيهِ","concerning it"],["تَخْتَلِفُونَ","differing"]]],"718":["(Dan hendaklah kamu putuskan perkara di antara mereka dengan apa yang diturunkan Allah dan janganlah kamu ikuti hawa nafsu mereka dan berhati-hatilah terhadap mereka) agar (supaya mereka) tidak (memfitnahmu) artinya menyesatkanmu (dari sebagian yang telah diturunkan Allah kepadamu. Jika mereka berpaling) dari hukum yang diturunkan dan bermaksud mengubahnya (maka ketahuilah bahwasanya Allah menghendaki akan menimpakan kepada mereka musibah) hukuman di dunia (disebabkan sebagian dosa-dosa mereka) yang mereka perbuat di antaranya berpaling itu. Dan akan membalas semua dosa itu di akhirat kelak. (Dan sesungguhnya banyak di antara manusia itu orang-orang yang fasik.)",[["وَأَنِ","And that"],["ٱحْكُم","you judge"],["بَيْنَهُم","between them"],["بِمَآ","by what"],["أَنزَلَ","(has) revealed"],["ٱللَّهُ","Allah"],["وَلَا","and (do) not"],["تَتَّبِعْ","follow"],["أَهْوَآءَهُمْ","their vain desires"],["وَٱحْذَرْهُمْ","and beware of them"],["أَن","lest"],["يَفْتِنُوكَ","they tempt you away"],["عَنۢ","from"],["بَعْضِ","some"],["مَآ","(of) what"],["أَنزَلَ","has revealed"],["ٱللَّهُ","Allah"],["إِلَيْكَ ۖ","to you"],["فَإِن","And if"],["تَوَلَّوْا۟","they turn away"],["فَٱعْلَمْ","then know that"],["أَنَّمَا","only"],["يُرِيدُ","intends"],["ٱللَّهُ","Allah"],["أَن","to"],["يُصِيبَهُم","afflict them"],["بِبَعْضِ","for some"],["ذُنُوبِهِمْ ۗ","(of) their sins"],["وَإِنَّ","And indeed"],["كَثِيرًۭا","many"],["مِّنَ","of"],["ٱلنَّاسِ","the people"],["لَفَـٰسِقُونَ","(are) defiantly disobedient"]]],"719":["(Apakah hukum jahiliah yang mereka kehendaki) dengan memakai ya dan ta; artinya dengan berpaling itu mereka hanyalah hendak bermanis mulut dan mengambil muka sedangkan pertanyaan di sini berarti sanggahan (dan siapakah) artinya tak seorang pun (yang lebih baik hukumannya daripada Allah bagi kaum) artinya di sisi orang-orang (yang yakin) kepada-Nya. Diistimewakan menyebutkan mereka karena hanya merekalah yang bersedia merenungkan hal ini.",[["أَفَحُكْمَ","Is it then the judgment"],["ٱلْجَـٰهِلِيَّةِ","(of the time of) ignorance"],["يَبْغُونَ ۚ","they seek"],["وَمَنْ","And who (is)"],["أَحْسَنُ","better"],["مِنَ","than"],["ٱللَّهِ","Allah"],["حُكْمًۭا","(in) judgment"],["لِّقَوْمٍۢ","for a people"],["يُوقِنُونَ","(who) firmly believe"]]],"720":["(Hai orang-orang yang beriman, janganlah kamu ambil orang-orang Yahudi dan Nasrani menjadi pemimpin) menjadi ikutanmu dan kamu cintai. (Sebagian mereka menjadi pemimpin bagi sebagian lainnya) karena kesatuan mereka dalam kekafiran. (Siapa di antara kamu mengambil mereka sebagai pemimpin, maka dia termasuk di antara mereka) artinya termasuk golongan mereka. (Sesungguhnya Allah tidak menunjuki orang-orang yang aniaya) karena mengambil orang-orang kafir sebagai pemimpin mereka.",[["۞ يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["لَا","(Do) not"],["تَتَّخِذُوا۟","take"],["ٱلْيَهُودَ","the Jews"],["وَٱلنَّصَـٰرَىٰٓ","and the Christians"],["أَوْلِيَآءَ ۘ","(as) allies"],["بَعْضُهُمْ","Some of them"],["أَوْلِيَآءُ","(are) allies"],["بَعْضٍۢ ۚ","(to) others"],["وَمَن","And whoever"],["يَتَوَلَّهُم","takes them as allies"],["مِّنكُمْ","among you"],["فَإِنَّهُۥ","then indeed, he"],["مِنْهُمْ ۗ","(is) of them"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَهْدِى","guide"],["ٱلْقَوْمَ","the people"],["ٱلظَّـٰلِمِينَ","the wrongdoing"]]],"721":["(Maka kamu lihat orang-orang yang di dalam hati mereka ada penyakit) yakni lemah akidahnya seperti Abdullah bin Ubai gembong munafik itu (bersegera kepada mereka) untuk mengambil mereka sebagai pemimpin (seraya katanya) mengemukakan alasan dari sikap mereka itu (\"Kami takut akan mendapat giliran bencana.\") misalnya giliran musim kemarau, kekalahan sedangkan urusan Muhammad tidak berketentuan sehingga tidak dapat membela kami. Berfirman Allah swt.: (Semoga Allah mendatangkan kemenangan) kepada rasul-Nya dengan mengembangkan agama-Nya (atau sesuatu keputusan dari sisi-Nya) misalnya dengan membuka kedok orang-orang munafik dan menyingkapkan rahasia mereka (sehingga mereka atas apa yang mereka rahasiakan dalam diri mereka) berupa keragu-raguan dan mengambil orang-orang kafir itu sebagai pemimpin (menjadi menyesal.)",[["فَتَرَى","And you see"],["ٱلَّذِينَ","those "],["فِى","in"],["قُلُوبِهِم","their hearts"],["مَّرَضٌۭ","(is) a disease"],["يُسَـٰرِعُونَ","they hasten"],["فِيهِمْ","to them"],["يَقُولُونَ","saying"],["نَخْشَىٰٓ","We fear"],["أَن","that"],["تُصِيبَنَا","(may) strike us"],["دَآئِرَ ةٌۭ ۚ","a misfortune"],["فَعَسَى","But perhaps"],["ٱللَّهُ","Allah"],["أَن","[that]"],["يَأْتِىَ","will bring"],["بِٱلْفَتْحِ","the victory"],["أَوْ","or"],["أَمْرٍۢ","a decision"],["مِّنْ","from"],["عِندِهِۦ","(of) Him"],["فَيُصْبِحُوا۟","Then they will become"],["عَلَىٰ","for"],["مَآ","what"],["أَسَرُّوا۟","they had concealed"],["فِىٓ","within"],["أَنفُسِهِمْ","themselves"],["نَـٰدِمِينَ","regretful"]]],"722":["(Dan berkatalah) dibaca yaquulu marfu` sebagai awal kata dengan memakai wawu atau tidak. Ada pula yang membaca yaquula manshub karena diathafkan kepada ya`tiya (orang-orang yang beriman) kepada kawan-kawan mereka keheranan; yakni jika topeng kedustaan mereka telah disingkapkan (\"Inikah orang-orang yang telah bersumpah dengan nama Allah secara bersungguh-sungguh) artinya sebenar-benarnya bersumpah (bahwa sesungguhnya mereka beserta kamu.\") dalam soal keagamaan. Firman Allah swt.: (\"Gugurlah) rusaklah/binasalah (amal perbuatan mereka yang baik) (maka jadilah mereka orang-orang yang merugi.\") baik di dunia dengan terbukanya rahasia mereka maupun di akhirat dengan datangnya azab dan siksa.",[["وَيَقُولُ","And will say"],["ٱلَّذِينَ","those who"],["ءَامَنُوٓا۟","believe"],["أَهَـٰٓؤُلَآءِ","Are these"],["ٱلَّذِينَ","those who"],["أَقْسَمُوا۟","swore"],["بِٱللَّهِ","by Allah"],["جَهْدَ","strongest"],["أَيْمَـٰنِهِمْ ۙ","(of) their oaths"],["إِنَّهُمْ","indeed, they"],["لَمَعَكُمْ ۚ","(were) with you"],["حَبِطَتْ","Became worthless"],["أَعْمَـٰلُهُمْ","their deeds"],["فَأَصْبَحُوا۟","and they became"],["خَـٰسِرِينَ","(the) losers"]]],"723":["(Hai orang-orang yang beriman! Siapa yang murtad) yartadda pakai idgam atau tidak; artinya murtad atau berbalik (di antara kamu dari agamanya) artinya berbalik kafir; ini merupakan pemberitahuan dari Allah swt. tentang berita gaib yang akan terjadi yang telah terlebih dahulu diketahui-Nya. Buktinya setelah Nabi Muhammad saw. wafat segolongan umat keluar dari agama Islam (maka Allah akan mendatangkan) sebagai ganti mereka (suatu kaum yang dicintai oleh Allah dan mereka pun mencintai-Nya) sabda Nabi saw., \"Mereka itu ialah kaum orang ini,\" sambil menunjuk kepada Abu Musa Al-Asyari; riwayat Hakim dalam sahihnya (bersikap lemah lembut terhadap orang-orang mukmin dan bersikap keras) atau tegas (terhadap orang-orang kafir. Mereka berjihad di jalan Allah dan tidak takut akan celaan orang yang suka mencela) dalam hal itu sebagaimana takutnya orang-orang munafik akan celaan orang-orang kafir. (Demikian itu) yakni sifat-sifat yang disebutkan tadi (adalah karunia Allah yang diberikan-Nya kepada siapa yang dikehendaki-Nya dan Allah Maha Luas) karunia-Nya (lagi Maha Mengetahui) akan yang patut menerimanya. Ayat ini turun ketika Ibnu Salam mengadu kepada Rasulullah, \"Wahai Rasulullah! Kaum kami telah mengucilkan kami!\"",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["مَن","Whoever"],["يَرْتَدَّ","turns back"],["مِنكُمْ","among you"],["عَن","from"],["دِينِهِۦ","his religion"],["فَسَوْفَ","then soon"],["يَأْتِى","(will be) brought"],["ٱللَّهُ","(by) Allah"],["بِقَوْمٍۢ","a people"],["يُحِبُّهُمْ","whom He loves"],["وَيُحِبُّونَهُۥٓ","and they love Him"],["أَذِلَّةٍ","humble"],["عَلَى","towards"],["ٱلْمُؤْمِنِينَ","the believers"],["أَعِزَّةٍ","(and) stern"],["عَلَى","towards"],["ٱلْكَـٰفِرِينَ","the disbelievers"],["يُجَـٰهِدُونَ","striving"],["فِى","in"],["سَبِيلِ","(the) way"],["ٱللَّهِ","(of) Allah"],["وَلَا","and not"],["يَخَافُونَ","fearing"],["لَوْمَةَ","the blame"],["لَآئِمٍۢ ۚ","(of) a critic"],["ذَٰلِكَ","That"],["فَضْلُ","(is the) Grace"],["ٱللَّهِ","(of) Allah"],["يُؤْتِيهِ","He grants"],["مَن","whom"],["يَشَآءُ ۚ","He wills"],["وَٱللَّهُ","And Allah"],["وَٰسِعٌ","(is) All-Encompassing"],["عَلِيمٌ","All-Knowing"]]],"724":["(Sesungguhnya yang menjadi penolongmu ialah Allah dan rasul-Nya serta orang-orang yang beriman yang mendirikan salat dan menunaikan zakat serta mereka rukuk) maksudnya khusyuk atau melakukan salat sunah.",[["إِنَّمَا","Only"],["وَلِيُّكُمُ","your ally"],["ٱللَّهُ","(is) Allah"],["وَرَسُولُهُۥ","and His Messenger"],["وَٱلَّذِينَ","and those who"],["ءَامَنُوا۟","believe"],["ٱلَّذِينَ","and those who"],["يُقِيمُونَ","establish"],["ٱلصَّلَوٰةَ","the prayer"],["وَيُؤْتُونَ","and give"],["ٱلزَّكَوٰةَ","zakah"],["وَهُمْ","and they"],["رَٰكِعُونَ","(are) those who bow down"]]],"725":["(Siapa yang mengambil Allah dan rasul-Nya serta orang-orang yang beriman sebagai penolongnya) lalu mereka dibela dan ditolongnya pula (maka sesungguhnya golongan agama Allah itulah yang akan menang) yang terjamin dengan pertolongan Allah swt. sedangkan pembelaan seseorang kepada agama Allah itu menjadi bukti bahwa ia dari golongan dan pengikut agama itu.",[["وَمَن","And whoever"],["يَتَوَلَّ","takes as an ally"],["ٱللَّهَ","Allah"],["وَرَسُولَهُۥ","and His Messenger"],["وَٱلَّذِينَ","and those who"],["ءَامَنُوا۟","believe"],["فَإِنَّ","then indeed"],["حِزْبَ","(the) party"],["ٱللَّهِ","(of) Allah "],["هُمُ","they"],["ٱلْغَـٰلِبُونَ","(are) the victorious"]]],"726":["(Hai orang-orang yang beriman! Janganlah kamu ambil orang-orang yang menjadikan agamamu sebagai olok-olok) ejekan (dan barang permainan di antara) min untuk penjelasan (orang-orang yang diberi Alkitab sebelumnya dan orang-orang kafir) atau orang-orang musyrik; dengan jar dan nashab (sebagai pemimpin dan bertakwalah kepada Allah) dengan tidak mengambil mereka sebagai pemimpin (jika kamu beriman) artinya sungguh-sungguh dalam keimanan kamu itu.",[["يَـٰٓأَيُّهَا","O you"],["ٱلَّذِينَ","who"],["ءَامَنُوا۟","believe"],["لَا","(Do) not"],["تَتَّخِذُوا۟","take"],["ٱلَّذِينَ","those who"],["ٱتَّخَذُوا۟","take"],["دِينَكُمْ","your religion"],["هُزُوًۭا","(in) ridicule"],["وَلَعِبًۭا","and fun"],["مِّنَ","from"],["ٱلَّذِينَ","those who"],["أُوتُوا۟","are given"],["ٱلْكِتَـٰبَ","the Book"],["مِن","from"],["قَبْلِكُمْ","before you"],["وَٱلْكُفَّارَ","and the disbelievers"],["أَوْلِيَآءَ ۚ","(as) allies"],["وَٱتَّقُوا۟","And fear"],["ٱللَّهَ","Allah"],["إِن","if"],["كُنتُم","you are"],["مُّؤْمِنِينَ","believers"]]],"727":["(Dan) orang-orang yang (apabila kamu menyeru) atau memanggil mereka (untuk salat) yaitu dengan azan (mereka menjadikannya) salat itu (sebagai bahan olok-olok dan permainan) yakni dengan mempermainkan dan menertawakannya. (Demikian itu) maksudnya sikap mereka itu (adalah karena mereka) disebabkan oleh karena mereka (kaum yang tak mau berpikir). Ayat berikut ini diturunkan ketika orang-orang Yahudi menanyakan kepada Nabi saw., \"Kepada rasul-rasul yang manakah kamu beriman?\" Jawabnya, \"Kepada Allah dan kepada apa-apa yang diturunkan kepada kami... sampai akhir ayat.\" Ketika Nabi saw. menyebut nama Isa, mereka berkata, \"Sepengetahuan kami tak ada agama yang lebih buruk dari agamamu!\"",[["وَإِذَا","And when"],["نَادَيْتُمْ","you make a call"],["إِلَى","for"],["ٱلصَّلَوٰةِ","the prayer"],["ٱتَّخَذُوهَا","they take it"],["هُزُوًۭا","(in) ridicule"],["وَلَعِبًۭا ۚ","and fun"],["ذَٰلِكَ","That"],["بِأَنَّهُمْ","(is) because they"],["قَوْمٌۭ","(are) a people"],["لَّا","(who do) not"],["يَعْقِلُونَ","understand"]]],"728":["(Katakanlah, \"Hai ahli kitab! Apakah kamu menyalahkan) menolak (kami hanya karena kami beriman kepada Allah, kepada apa yang diturunkan kepada kami dan apa yang diturunkan sebelumnya) yakni kepada nabi-nabi yang terdahulu (dan bahwa kebanyakan di antara kamu orang-orang yang fasik?\") diathafkan kepada an aamannaa sedangkan maksudnya ialah: tak ada yang kamu salahkan kecuali hanyalah keimanan kami yang rupanya tidak kamu setujui. Sikap tersebut membuat kalian pantas disebut orang-orang yang fasik. Padahal hal ini merupakan hal yang sudah tidak boleh diingkari.",[["قُلْ","Say"],["يَـٰٓأَهْلَ","O People"],["ٱلْكِتَـٰبِ","(of) the Book"],["هَلْ","Do"],["تَنقِمُونَ","you resent"],["مِنَّآ","[of] us"],["إِلَّآ","except"],["أَنْ","that"],["ءَامَنَّا","we believe"],["بِٱللَّهِ","in Allah"],["وَمَآ","and what"],["أُنزِلَ","has been revealed"],["إِلَيْنَا","to us"],["وَمَآ","and what"],["أُنزِلَ","was revealed"],["مِن","from"],["قَبْلُ","before"],["وَأَنَّ","and that"],["أَكْثَرَكُمْ","most of you"],["فَـٰسِقُونَ","(are) defiantly disobedient"]]],"729":["(Katakanlah, \"Apakah akan kukabarkan kepadamu) kuberitakan (orang-orang yang lebih buruk) lagi daripada warga (demikian) yang kamu salahkan itu (mengenai pembalasannya) asal artinya ialah pahalanya (di sisi Allah) yaitu (orang yang dikutuk oleh Allah) artinya dijauhkan dari rahmat-Nya (dan dimurkai-Nya serta di antara mereka ada yang dijadikan-Nya kera dan babi) dengan merubah bentuknya (dan) orang (yang menyembah tagut) yakni setan dengan jalan menaatinya. Pada minhum ditekankan arti man pada lafal sebelumnya yang dimaksud ialah orang-orang Yahudi. Menurut satu qiraat dibaca `abuda dengan diidhafatkan kepada yang sesudahnya sebagai isim jamak dari `abd dan dinashabkan karena ma`thuf kepada qiradah. (Mereka itu lebih buruk tempatnya) karena mereka menempati neraka berfungsi sebagai tamyiz (dan lebih tersesat lagi dari jalan yang lurus) dari jalan yang benar. Sawaa` arti asalnya ialah pertengahan. Disebutkan buruk dan lebih tersesat untuk mengimbangi ucapan mereka, 'Sepengetahuan kami tak ada agama yang lebih buruk dari agamamu.'\"",[["قُلْ","Say"],["هَلْ","Shall"],["أُنَبِّئُكُم","I inform you"],["بِشَرٍّۢ","(of) worse"],["مِّن","than"],["ذَٰلِكَ","that"],["مَثُوبَةً","(as) recompense"],["عِندَ","from"],["ٱللَّهِ ۚ","Allah"],["مَن","Whom"],["لَّعَنَهُ","has (been) cursed"],["ٱللَّهُ","(by) Allah"],["وَغَضِبَ","and He became angry"],["عَلَيْهِ","with him"],["وَجَعَلَ","and made"],["مِنْهُمُ","of them"],["ٱلْقِرَدَةَ","[the] apes"],["وَٱلْخَنَازِيرَ","and [the] swines"],["وَعَبَدَ","and (who) worshipped"],["ٱلطَّـٰغُوتَ ۚ","the false deities"],["أُو۟لَـٰٓئِكَ","Those"],["شَرٌّۭ","(are) worse"],["مَّكَانًۭا","(in) position"],["وَأَضَلُّ","and farthest astray"],["عَن","from"],["سَوَآءِ","(the) even"],["ٱلسَّبِيلِ","way"]]],"730":["(Dan jika mereka datang kepadamu) yaitu orang-orang Yahudi munafik (mereka berkata, \"Kami beriman,\" padahal mereka masuk) kepadamu dengan membawa (kekafiran dan mereka keluar) daripadamu (dengan membawa kekafiran pula) mereka tidak beriman (dan Allah lebih mengetahui apa yang mereka sembunyikan) itu berupa kemunafikan.",[["وَإِذَا","And when"],["جَآءُوكُمْ","they come to you"],["قَالُوٓا۟","they say"],["ءَامَنَّا","We believe"],["وَقَد","But certainly"],["دَّخَلُوا۟","they entered"],["بِٱلْكُفْرِ","with disbelief"],["وَهُمْ","and they"],["قَدْ","certainly"],["خَرَجُوا۟","went out"],["بِهِۦ ۚ","with it"],["وَٱللَّهُ","And Allah"],["أَعْلَمُ","knows best"],["بِمَا","[of] what"],["كَانُوا۟","they were"],["يَكْتُمُونَ","hiding"]]],"731":["(Dan akan kamu lihat banyak di antara mereka) maksudnya orang-orang Yahudi (bersegera) artinya cepat terlibat dalam (berbuat dosa) kedustaan (dan permusuhan) keaniayaan (serta memakan barang yang haram) seperti uang suap dan lain-lain (sungguh, amat buruklah apa yang mereka kerjakan) itu; yakni perbuatan-perbuatan yang mereka lakukan tadi.",[["وَتَرَىٰ","And you see"],["كَثِيرًۭا","many"],["مِّنْهُمْ","of them"],["يُسَـٰرِعُونَ","hastening"],["فِى","into"],["ٱلْإِثْمِ","[the] sin"],["وَٱلْعُدْوَٰنِ","and [the] transgression"],["وَأَكْلِهِمُ","and eating"],["ٱلسُّحْتَ ۚ","the forbidden"],["لَبِئْسَ","Surely evil"],["مَا","(is) what"],["كَانُوا۟","they were"],["يَعْمَلُونَ","doing"]]],"732":["(Kenapa orang-orang alim dan para pendeta mereka tak melarang mereka mengucapkan dosa) artinya kata-kata dusta (dan memakan barang yang haram? Sungguh, amat buruklah apa yang mereka perbuat itu) yaitu tidak melarang mereka berbuat kejahatan.",[["لَوْلَا","Why (do) not"],["يَنْهَىٰهُمُ","forbid them"],["ٱلرَّبَّـٰنِيُّونَ","the Rabbis"],["وَٱلْأَحْبَارُ","and the religious scholars"],["عَن","from"],["قَوْلِهِمُ","their saying"],["ٱلْإِثْمَ","the sinful"],["وَأَكْلِهِمُ","and their eating"],["ٱلسُّحْتَ ۚ","(of) the forbidden"],["لَبِئْسَ","Surely, evil"],["مَا","(is) what"],["كَانُوا۟","they used to"],["يَصْنَعُونَ","do"]]],"733":["(Orang-orang Yahudi berkata) setelah mereka ditimpa kesusahan disebabkan mendustakan Nabi saw. padahal selama ini mereka adalah orang-orang yang paling mampu dan paling banyak harta. (\"Tangan Allah terbelenggu.\") artinya dikatup hingga terhalang untuk menyebarkan rezeki kepada kita. Ucapan itu merupakan sindiran terhadap kikirnya Allah swt. buat melimpahkan rezeki. Firman Allah swt.: (\"Tangan merekalah yang dibelenggu.\") dari berbuat kebaikan hingga tak mau melakukannya. Ini sebagai doa terhadap mereka (dan mereka dikutuk disebabkan apa yang telah mereka katakan itu. Bahkan kedua tangan-Nya terbuka lebar) merupakan simbol tentang kiasan tentang sifat Allah Yang Maha Pemurah. Pujian kepada tangan ini untuk menunjukkan banyak dan melimpah-ruah karena segala sesuatu yang diberikan oleh seorang dermawan berupa harta melalui tangannya. (Dia memberi nafkah sebagaimana dikehendaki-Nya) apakah akan diperlapang ataukah akan dipersempit-Nya, tidak satu pun dapat menghalangi-Nya. (Dan apa yang diturunkan kepadamu dari Tuhanmu, berarti akan menambah banyak kedurhakaan dan kekafiran mereka) karena kekafiran mereka kepadanya. (Dan Kami timbulkan di antara mereka permusuhan dan kebencian sampai hari kiamat) hingga setiap golongan menentang dan memusuhi lainnya. (Setiap mereka menyalakan api peperangan) maksudnya untuk memerangi Nabi Muhammad saw. (dipadamkannya oleh Allah) artinya setiap mereka bermaksud, maka ditolak oleh Allah (dan mereka berbuat kerusakan di muka bumi) maksudnya menghancurkannya dengan berbuat maksiat (dan Allah tidak menyukai orang-orang yang berbuat kerusakan).",[["وَقَالَتِ","And said"],["ٱلْيَهُودُ","the Jews"],["يَدُ","The Hand"],["ٱللَّهِ","(of) Allah"],["مَغْلُولَةٌ ۚ","(is) chained"],["غُلَّتْ","Are chained"],["أَيْدِيهِمْ","their hands"],["وَلُعِنُوا۟","and they have been cursed"],["بِمَا","for what"],["قَالُوا۟ ۘ","they said"],["بَلْ","Nay"],["يَدَاهُ","His Hands"],["مَبْسُوطَتَانِ","(are) stretched out"],["يُنفِقُ","He spends"],["كَيْفَ","how"],["يَشَآءُ ۚ","He wills"],["وَلَيَزِيدَنَّ","And surely increase"],["كَثِيرًۭا","many"],["مِّنْهُم","of them"],["مَّآ","what"],["أُنزِلَ","has been revealed"],["إِلَيْكَ","to you"],["مِن","from"],["رَّبِّكَ","your Lord"],["طُغْيَـٰنًۭا","(in) rebellion"],["وَكُفْرًۭا ۚ","and disbelief"],["وَأَلْقَيْنَا","And We have cast"],["بَيْنَهُمُ","among them"],["ٱلْعَدَٰوَةَ","[the] enmity"],["وَٱلْبَغْضَآءَ","and [the] hatred"],["إِلَىٰ","till"],["يَوْمِ","(the) Day"],["ٱلْقِيَـٰمَةِ ۚ","(of) the Resurrection"],["كُلَّمَآ","Every time"],["أَوْقَدُوا۟","they kindled"],["نَارًۭا","(the) fire"],["لِّلْحَرْبِ","of [the] war"],["أَطْفَأَهَا","it (was) extinguished"],["ٱللَّهُ ۚ","(by) Allah"],["وَيَسْعَوْنَ","And they strive"],["فِى","in"],["ٱلْأَرْضِ","the earth"],["فَسَادًۭا ۚ","spreading corruption"],["وَٱللَّهُ","And Allah"],["لَا","(does) not"],["يُحِبُّ","love"],["ٱلْمُفْسِدِينَ","the corrupters"]]],"734":["(Dan sekiranya Ahli Kitab itu beriman) kepada Nabi Muhammad saw. (dan bertakwa) artinya menjaga diri dari kekafiran (pastilah Kami hapus dari mereka kesalahan mereka dan Kami masukkan mereka ke dalam surga-surga kenikmatan).",[["وَلَوْ","And if"],["أَنَّ","that"],["أَهْلَ","(the) People"],["ٱلْكِتَـٰبِ","(of) the Book"],["ءَامَنُوا۟","(had) believed"],["وَٱتَّقَوْا۟","and feared (Allah)"],["لَكَفَّرْنَا","surely We (would have) removed"],["عَنْهُمْ","from them"],["سَيِّـَٔاتِهِمْ","their evil (deeds)"],["وَلَأَدْخَلْنَـٰهُمْ","and surely We (would have) admitted them"],["جَنَّـٰتِ","(to) Gardens"],["ٱلنَّعِيمِ","(of) Bliss"]]],"735":["(Dan sekiranya mereka menegakkan Taurat dan Injil) mengamalkan ajarannya, di antaranya beriman kepada Nabi saw. (dan apa yang diturunkan kepada mereka) maksudnya kitab-kitab (dari Tuhan mereka, tentulah mereka akan beroleh makanan dari atas mereka dan dari bawah kaki mereka) maksudnya dilapangkan-Nya rezeki dan dilimpahkan-Nya atas mereka dari segenap penjuru. (Di antara mereka ada umat) maksudnya golongan (yang adil) yakni mengamalkannya dan mereka itulah yang beriman kepada Nabi saw., seperti Abdullah bin Salam dan kawan-kawannya (tetapi banyak di antara mereka amat jelek atau amat buruk apa yang mereka kerjakan.)",[["وَلَوْ","And if"],["أَنَّهُمْ","that they"],["أَقَامُوا۟","had stood firmly"],["ٱلتَّوْرَىٰةَ","(by) the Taurat"],["وَٱلْإِنجِيلَ","and the Injeel"],["وَمَآ","and what"],["أُنزِلَ","was revealed"],["إِلَيْهِم","to them"],["مِّن","from"],["رَّبِّهِمْ","their Lord"],["لَأَكَلُوا۟","surely they (would have) eaten"],["مِن","from"],["فَوْقِهِمْ","above them"],["وَمِن","and from"],["تَحْتِ","beneath"],["أَرْجُلِهِم ۚ","their feet"],["مِّنْهُمْ","Among them"],["أُمَّةٌۭ","(is) a community"],["مُّقْتَصِدَةٌۭ ۖ","moderate"],["وَكَثِيرٌۭ","but many"],["مِّنْهُمْ","of them "],["سَآءَ","evil"],["مَا","(is) what"],["يَعْمَلُونَ","they do"]]],"736":["(Hai rasul, sampaikanlah) semua (yang diturunkan kepadamu dari Tuhanmu) dan janganlah kamu sembunyikan sesuatu pun daripadanya karena takut akan mendapatkan hal-hal yang tidak diinginkan (dan jika tidak kamu lakukan) tidak kamu sampaikan semua yang diturunkan padamu itu (berarti kamu tidak menyampaikan risalah-Nya) risalah dengan tunggal atau jamak karena menyembunyikan sebagian berarti menyembunyikan semuanya. (Dan Allah memelihara kamu dari manusia) agar tidak sampai membunuhmu. Pada mulanya Rasulullah saw. itu dikawal sampai turun ayat ini, lalu sabdanya, \"Pergilah karena sesungguhnya Allah memeliharaku!\" Riwayat Hakim. (Sesungguhnya Allah tidak memberikan bimbingan kepada kaum yang kafir.)",[["۞ يَـٰٓأَيُّهَا","O"],["ٱلرَّسُولُ","Messenger"],["بَلِّغْ","Convey"],["مَآ","what"],["أُنزِلَ","has been revealed"],["إِلَيْكَ","to you"],["مِن","from"],["رَّبِّكَ ۖ","your Lord"],["وَإِن","and if"],["لَّمْ","not"],["تَفْعَلْ","you do"],["فَمَا","then not"],["بَلَّغْتَ","you (have) conveyed"],["رِسَالَتَهُۥ ۚ","His Message"],["وَٱللَّهُ","And Allah"],["يَعْصِمُكَ","will protect you"],["مِنَ","from"],["ٱلنَّاسِ ۗ","the people"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["لَا","(does) not"],["يَهْدِى","guide"],["ٱلْقَوْمَ","the people"],["ٱلْكَـٰفِرِينَ","the disbelieving"]]],"737":["(Katakanlah \"Hai Ahli Kitab! Kamu tidaklah berada dalam sesuatu agama) tidak dianggap beragama (hingga kamu menjalankan Taurat dan Injil dan apa yang diturunkan kepadamu dari Tuhanmu) yakni dengan mengamalkan apa yang terdapat di dalamnya, di antaranya beriman kepadaku. (Sesungguhnya apa yang diturunkan kepadamu dari Tuhanmu hanyalah akan menambah kedurhakaan dan kekafiran kepada kebanyakan mereka) maksudnya bahwa disebabkan kekafiran mereka tadi, maka Alquran yang diturunkan padamu itu hanyalah menambah kekafiran dan kedurhakaan mereka, jadi bukan petunjuk dan keimanan. (Maka janganlah kamu berduka-cita) atau bersedih hati (terhadap orang-orang yang kafir.\") jika mereka tak mau beriman, tidak usah mereka itu dihiraukan.",[["قُلْ","Say"],["يَـٰٓأَهْلَ","O People"],["ٱلْكِتَـٰبِ","(of) the Book"],["لَسْتُمْ","You are not"],["عَلَىٰ","on"],["شَىْءٍ","anything"],["حَتَّىٰ","until"],["تُقِيمُوا۟","you stand firmly"],["ٱلتَّوْرَىٰةَ","(by) the Taurat"],["وَٱلْإِنجِيلَ","and the Injeel"],["وَمَآ","and what"],["أُنزِلَ","has been revealed"],["إِلَيْكُم","to you"],["مِّن","from"],["رَّبِّكُمْ ۗ","your Lord"],["وَلَيَزِيدَنَّ","And surely increase"],["كَثِيرًۭا","many"],["مِّنْهُم","of them"],["مَّآ","what"],["أُنزِلَ","has been revealed"],["إِلَيْكَ","to you"],["مِن","from"],["رَّبِّكَ","your Lord"],["طُغْيَـٰنًۭا","(in) rebellion"],["وَكُفْرًۭا ۖ","and disbelief"],["فَلَا","So (do) not"],["تَأْسَ","grieve"],["عَلَى","over"],["ٱلْقَوْمِ","the people"],["ٱلْكَـٰفِرِينَ","the disbelieving"]]],"738":["(Sesungguhnya orang-orang mukmin orang-orang Yahudi) menjadi mubtada (kaum Shabiin) satu sekte dari Yahudi (dan orang-orang Nasrani) yang menjadi badal dari mubtada ialah (siapa saja yang benar-benar beriman) dari kalangan mereka (kepada Allah, hari kemudian dan beramal saleh, maka tidak ada kekhawatiran terhadap mereka dan tidak pula mereka bersedih hati) dalam menghadapi hari kemudian sebagai khabar dari mubtada dan yang menunjukkan kepada khabarnya inna.",[["إِنَّ","Indeed"],["ٱلَّذِينَ","those who"],["ءَامَنُوا۟","believed"],["وَٱلَّذِينَ","and those who"],["هَادُوا۟","became Jews"],["وَٱلصَّـٰبِـُٔونَ","and the Sabians"],["وَٱلنَّصَـٰرَىٰ","and the Christians"],["مَنْ","whoever"],["ءَامَنَ","believed"],["بِٱللَّهِ","in Allah"],["وَٱلْيَوْمِ","and the Day"],["ٱلْـَٔاخِرِ","the Last"],["وَعَمِلَ","and did"],["صَـٰلِحًۭا","good deeds"],["فَلَا","then no"],["خَوْفٌ","fear"],["عَلَيْهِمْ","on them"],["وَلَا","and not"],["هُمْ","they"],["يَحْزَنُونَ","will grieve"]]],"739":["(Sesungguhnya Kami telah mengambil perjanjian dari Bani Israel) untuk beriman kepada Allah dan Rasul-Nya (dan telah Kami utus kepada mereka rasul-rasul tetapi setiap datang kepada mereka seorang rasul) dari kalangan mereka sendiri (dengan membawa apa yang tidak diingini oleh hawa nafsu mereka) yaitu berupa perkara yang hak/benar maka mereka tidak mempercayainya (sebagian) dari rasul-rasul itu (mereka dustakan dan sebagian yang lain) dari rasul-rasul itu (mereka bunuh) seperti Nabi Zakaria dan Nabi Yahya. Pengungkapan dengan lafal yaqtuluuna/fi`il mudhari` bukannya dengan lafal qataluu/fi`il madhi menggambarkan tentang keadaan yang sedang berlangsung di masa lalu karena adanya fashilah/pemisah.",[["لَقَدْ","Certainly"],["أَخَذْنَا","We took"],["مِيثَـٰقَ","a Covenant"],["بَنِىٓ","(from the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"],["وَأَرْسَلْنَآ","and We sent"],["إِلَيْهِمْ","to them"],["رُسُلًۭا ۖ","Messengers"],["كُلَّمَا","Whenever"],["جَآءَهُمْ","came to them"],["رَسُولٌۢ","any Messenger"],["بِمَا","with what"],["لَا","not"],["تَهْوَىٰٓ","desired"],["أَنفُسُهُمْ","their souls"],["فَرِيقًۭا","a group"],["كَذَّبُوا۟","they denied"],["وَفَرِيقًۭا","and a group"],["يَقْتُلُونَ","they kill"]]],"740":["(Dan mereka mengira) mereka menduga (bahwa tidak akan terjadi) dengan dibaca rafa` maka an menjadi mukhaffafah/tidak beramal dan dibaca nashab maka an dapat menashabkan/beramal; artinya tidak bakalan terjadi (fitnah) siksaan yang menimpa diri mereka sebagai balasan dari perbuatan mendustakan para rasul dan berani membunuh mereka (sebagai akibatnya mereka menjadi buta) dari perkara yang hak hingga mereka tidak bisa melihatnya (dan mereka menjadi tuli) tidak bisa mendengar perkara yang hak (kemudian Allah menerima tobat mereka) tatkala mereka mau bertobat (kemudian mereka kembali menjadi buta dan tuli) untuk kedua kalinya (demikianlah kebanyakan dari kalangan mereka) lafal katsiirun sebagai dhamir/kata ganti (dan Allah Maha Melihat terhadap apa yang mereka kerjakan) untuk itu Ia membalas mereka sesuai dengan apa-apa yang telah mereka kerjakan.",[["وَحَسِبُوٓا۟","And they thought"],["أَلَّا","that not"],["تَكُونَ","will be (for them)"],["فِتْنَةٌۭ","a trial"],["فَعَمُوا۟","so they became blind"],["وَصَمُّوا۟","and they became deaf"],["ثُمَّ","Then"],["تَابَ","turned"],["ٱللَّهُ","Allah"],["عَلَيْهِمْ","to them"],["ثُمَّ","then (again)"],["عَمُوا۟","they became blind"],["وَصَمُّوا۟","and they became deaf"],["كَثِيرٌۭ","many"],["مِّنْهُمْ ۚ","of them"],["وَٱللَّهُ","And Allah"],["بَصِيرٌۢ","(is) All-Seer"],["بِمَا","of what"],["يَعْمَلُونَ","they do"]]],"741":["(Sesungguhnya telah kafirlah orang-orang yang mengatakan, \"Sesungguhnya Allah ialah Almasih putra Maryam.\") di masa sebelumnya telah terjadi hal yang serupa (padahal telah berkata) kepada mereka (Almasih, \"Hai Bani Israel, sembahlah Allah Tuhanku dan Tuhanmu) sesungguhnya aku ini hanyalah seorang hamba Allah dan bukan Tuhan (sesungguhnya orang-orang yang mempersekutukan sesuatu dengan Allah) menyembah kepada selain Allah (maka pasti Allah mengharamkan kepadanya surga) Allah melarangnya untuk memasuki surga (dan tempatnya ialah neraka dan tidak ada bagi orang-orang lalim itu seorang) lafal min adalah tambahan (penolong.\") yang dapat mencegah siksaan Allah terhadap diri mereka.",[["لَقَدْ","Certainly"],["كَفَرَ","disbelieved"],["ٱلَّذِينَ","those who"],["قَالُوٓا۟","say"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah "],["هُوَ","He"],["ٱلْمَسِيحُ","(is) the Messiah"],["ٱبْنُ","son"],["مَرْيَمَ ۖ","(of) Maryam"],["وَقَالَ","While said"],["ٱلْمَسِيحُ","the Messiah"],["يَـٰبَنِىٓ","O Children"],["إِسْرَٰٓءِيلَ","(of) Israel"],["ٱعْبُدُوا۟","Worship"],["ٱللَّهَ","Allah"],["رَبِّى","my Lord"],["وَرَبَّكُمْ ۖ","and your Lord"],["إِنَّهُۥ","Indeed, he"],["مَن","who"],["يُشْرِكْ","associates partners"],["بِٱللَّهِ","with Allah"],["فَقَدْ","then surely"],["حَرَّمَ","(has) forbidden"],["ٱللَّهُ","Allah"],["عَلَيْهِ","for him"],["ٱلْجَنَّةَ","Paradise"],["وَمَأْوَىٰهُ","and his abode"],["ٱلنَّارُ ۖ","(will be) the Fire"],["وَمَا","And not"],["لِلظَّـٰلِمِينَ","for the wrongdoers"],["مِنْ","any"],["أَنصَارٍۢ","helpers"]]],"742":["(Sesungguhnya telah kafirlah orang-orang yang mengatakan, \"Bahwasanya Allah salah seorang) dari tuhan (yang tiga) artinya salah seorang dari tuhan-tuhan yang jumlahnya tiga dan dua orang lainnya yang dianggap tuhan ialah Nabi Isa beserta ibunya. Mereka yang berpendapat demikian adalah golongan dari orang-orang Nasrani (padahal sekali-kali tidak ada Tuhan selain dari Tuhan Yang Esa. Dan jika mereka tidak berhenti dari apa yang mereka katakan itu) berhenti dari menigakan Allah, kemudian kembali mengesakan-Nya (pasti akan menimpa kepada orang-orang yang kafir) artinya mereka yang menetapi kekafirannya (di antara mereka siksaan yang pedih\") siksaan yang sungguh amat memedihkan, yaitu siksaan neraka.",[["لَّقَدْ","Certainly"],["كَفَرَ","disbelieved"],["ٱلَّذِينَ","those who"],["قَالُوٓا۟","say"],["إِنَّ","Indeed"],["ٱللَّهَ","Allah"],["ثَالِثُ","(is the) third"],["ثَلَـٰثَةٍۢ ۘ","(of) three"],["وَمَا","And (there is) no"],["مِنْ","[of]"],["إِلَـٰهٍ","god"],["إِلَّآ","except"],["إِلَـٰهٌۭ","(the) God"],["وَٰحِدٌۭ ۚ","(the) One"],["وَإِن","And if"],["لَّمْ","not"],["يَنتَهُوا۟","they desist"],["عَمَّا","from what"],["يَقُولُونَ","they are saying"],["لَيَمَسَّنَّ","surely will afflict"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["مِنْهُمْ","among them"],["عَذَابٌ","a punishment"],["أَلِيمٌ","painful"]]],"743":["(Maka mengapa mereka tidak bertobat kepada Allah dan memohon ampun kepada-Nya) atas apa yang telah mereka katakan; pertanyaan di sini menunjukkan kepada makna celaan. (Dan Allah Maha Pengampun) terhadap orang yang mau bertobat (lagi Maha Penyayang) kepadanya.",[["أَفَلَا","So will not"],["يَتُوبُونَ","they turn in repentance"],["إِلَى","to"],["ٱللَّهِ","Allah"],["وَيَسْتَغْفِرُونَهُۥ ۚ","and seek His forgiveness"],["وَٱللَّهُ","And Allah"],["غَفُورٌۭ","(is) Oft-Forgiving"],["رَّحِيمٌۭ","Most Merciful"]]],"744":["(Almasih putra Maryam itu hanyalah seorang rasul yang sesungguhnya telah berlalu) telah lewat (sebelumnya beberapa rasul) maka dia pun akan berlalu/mati seperti mereka; dia bukanlah Tuhan seperti apa yang telah mereka sangkakan, jika memang demikian maka niscaya ia pun tidak akan berlalu/mati (dan ibunya seorang yang amat benar) seorang wanita yang teramat benar (keduanya biasa memakan makanan) sama seperti makhluk-makhluk hidup lainnya, maka siapa pun yang keadaannya demikian berarti dia bukanlah Tuhan karena ia masih membutuhkan makanan, lemah dan masih mengeluarkan kencing dan kotoran sebagai akibat dari makanan itu. (Perhatikanlah) dengan penuh rasa ketakjuban (bagaimana Kami menjelaskan kepada mereka, ahli kitab, tanda-tanda kekuasaan Kami) yang menunjukkan keesaan Kami (kemudian perhatikanlah bagaimana) lafal annaa adalah kata tanya (mendustakannya) mereka berpaling dari perkara hak yang disertai dengan bukti yang jelas.",[["مَّا","Not"],["ٱلْمَسِيحُ","(is) the Messiah"],["ٱبْنُ","son"],["مَرْيَمَ","(of) Maryam"],["إِلَّا","but"],["رَسُولٌۭ","a Messenger"],["قَدْ","certainly"],["خَلَتْ","had passed"],["مِن","from"],["قَبْلِهِ","before him"],["ٱلرُّسُلُ","the Messengers"],["وَأُمُّهُۥ","And his mother"],["صِدِّيقَةٌۭ ۖ","(was) truthful"],["كَانَا","They both used to"],["يَأْكُلَانِ","eat"],["ٱلطَّعَامَ ۗ","[the] food"],["ٱنظُرْ","See"],["كَيْفَ","how"],["نُبَيِّنُ","We make clear"],["لَهُمُ","to them"],["ٱلْـَٔايَـٰتِ","the Signs"],["ثُمَّ","then"],["ٱنظُرْ","see"],["أَنَّىٰ","how"],["يُؤْفَكُونَ","they are deluded"]]],"745":["(Katakanlah, \"Mengapa kamu menyembah selain daripada Allah) selain-Nya (sesuatu yang tidak dapat memberi mara bahaya kepadamu dan tidak pula memberi manfaat?\" Dan Allahlah Yang Maha Mendengar) terhadap perkataan-perkataanmu (lagi Maha Mengetahui) tentang tindak-tandukmu; kata istifham/kata tanya di sini menunjukkan keingkaran.",[["قُلْ","Say"],["أَتَعْبُدُونَ","Do you worship"],["مِن","from"],["دُونِ","besides"],["ٱللَّهِ","Allah"],["مَا","what"],["لَا","not"],["يَمْلِكُ","has power"],["لَكُمْ","to (cause) you"],["ضَرًّۭا","any harm"],["وَلَا","and not"],["نَفْعًۭا ۚ","any benefit"],["وَٱللَّهُ","while Allah"],["هُوَ","He"],["ٱلسَّمِيعُ","(is) the All-Hearing"],["ٱلْعَلِيمُ","the All-Knowing"]]],"746":["(Katakanlah, \"Hai Ahli Kitab!) para pemeluk agama Yahudi dan agama Nasrani (Janganlah kamu berlebih-lebihan) janganlah kamu melampaui batas (dalam agamamu) secara berlebih-lebihan (dengan cara tidak benar) yaitu dengan cara merendahkan Nabi Isa atau kamu mengangkatnya secara berlebihan dari apa yang seharusnya (dan janganlah kamu mengikuti hawa nafsu orang-orang yang telah sesat dahulunya sebelum kedatangan Nabi Muhammad) mengikuti cara berlebih-lebihan yang pernah dilakukan oleh para pendahulu mereka (dan mereka telah menyesatkan kebanyakan) manusia (dan mereka tersesat dari jalan yang lurus.\") jalan yang hak; lafal as-sawaa` asalnya bermakna pertengahan.",[["قُلْ","Say"],["يَـٰٓأَهْلَ","O People"],["ٱلْكِتَـٰبِ","(of) the Book"],["لَا","(Do) not"],["تَغْلُوا۟","exceed"],["فِى","in"],["دِينِكُمْ","your religion"],["غَيْرَ","other than"],["ٱلْحَقِّ","the truth"],["وَلَا","and (do) not"],["تَتَّبِعُوٓا۟","follow"],["أَهْوَآءَ","(vain) desires"],["قَوْمٍۢ","(of) a people"],["قَدْ","certainly"],["ضَلُّوا۟","who went astray"],["مِن","from"],["قَبْلُ","before"],["وَأَضَلُّوا۟","and they misled"],["كَثِيرًۭا","many"],["وَضَلُّوا۟","and they have strayed"],["عَن","from"],["سَوَآءِ","(the) right"],["ٱلسَّبِيلِ","[the] way"]]],"747":["(Telah dilaknat orang-orang kafir dari Bani Israel melalui lisan Daud) yaitu Nabi Daud mendoakan/menyerapah mereka hingga mereka berubah ujud menjadi kera-kera; mereka adalah orang-orang dari kalangan Bani Israel yang menduduki tanah Ailah (dan Isa putra Maryam) yaitu Nabi Isa mendoakan/menyerapah mereka sehingga mereka berubah ujud menjadi babi-babi; mereka adalah orang-orang Bani Israel yang memiliki Al-Maidah/hidangan yang didatangkan dari langit (yang demikian itu) adalah laknat (disebabkan mereka durhaka dan melampaui batas).",[["لُعِنَ","Were cursed"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟","disbelieved"],["مِنۢ","from"],["بَنِىٓ","(the) Children"],["إِسْرَٰٓءِيلَ","(of) Israel"],["عَلَىٰ","by"],["لِسَانِ","(the) tongue"],["دَاوُۥدَ","(of) Dawood"],["وَعِيسَى","and Isa"],["ٱبْنِ","son"],["مَرْيَمَ ۚ","(of) Maryam"],["ذَٰلِكَ","that (was)"],["بِمَا","because"],["عَصَوا۟","they disobeyed"],["وَّكَانُوا۟","and they were"],["يَعْتَدُونَ","transgressing"]]],"748":["(Mereka satu sama lain tidak pernah melarang) artinya sebagian di antara mereka tidak pernah melarang sebagian lainnya (dari) kebiasaan (tindakan mungkar yang biasa mereka perbuat. Sesungguhnya amat buruklah apa yang selalu mereka perbuat) kebiasaan mereka dalam melakukan perbuatan mungkar itu.",[["كَانُوا۟","They had been"],["لَا","not"],["يَتَنَاهَوْنَ","forbidding each other"],["عَن","from"],["مُّنكَرٍۢ","wrongdoing"],["فَعَلُوهُ ۚ","they did [it]"],["لَبِئْسَ","Surely, evil"],["مَا","(was) what"],["كَانُوا۟","they were"],["يَفْعَلُونَ","doing"]]],"749":["(Kamu melihat) wahai Muhammad (kebanyakan dari mereka tolong-menolong dengan orang-orang yang kafir/musyrik) dari kalangan penduduk Mekah karena membencimu. (Sesungguhnya amat buruklah apa yang mereka sediakan untuk diri mereka) yaitu berupa amal perbuatan untuk bekal mereka di akhirat yang akibatnya (Allah murka terhadap mereka dan mereka akan kekal dalam siksaan.)",[["تَرَىٰ","You see"],["كَثِيرًۭا","many"],["مِّنْهُمْ","of them"],["يَتَوَلَّوْنَ","taking as allies"],["ٱلَّذِينَ","those who"],["كَفَرُوا۟ ۚ","disbelieved"],["لَبِئْسَ","Surely evil"],["مَا","(is) what"],["قَدَّمَتْ","sent forth"],["لَهُمْ","for them"],["أَنفُسُهُمْ","their souls"],["أَن","that"],["سَخِطَ","became angry"],["ٱللَّهُ","Allah"],["عَلَيْهِمْ","with them"],["وَفِى","and in"],["ٱلْعَذَابِ","the punishment"],["هُمْ","they"],["خَـٰلِدُونَ","(will) abide forever"]]],"750":["(Sekiranya mereka beriman kepada Allah, kepada Nabi) Muhammad (dan kepada apa yang diturunkan kepadanya niscaya mereka tidak akan mengambil orang-orang musyrik itu) orang-orang kafir (menjadi penolong-penolong tetapi kebanyakan dari mereka adalah orang-orang yang fasik/durhaka) mereka adalah orang-orang yang menyimpang dari keimanan.",[["وَلَوْ","And if"],["كَانُوا۟","they had"],["يُؤْمِنُونَ","believed"],["بِٱللَّهِ","in Allah"],["وَٱلنَّبِىِّ","and the Prophet"],["وَمَآ","and what"],["أُنزِلَ","has been revealed"],["إِلَيْهِ","to him"],["مَا","not"],["ٱتَّخَذُوهُمْ","they (would have) taken them"],["أَوْلِيَآءَ","(as) allies"],["وَلَـٰكِنَّ","[and] but"],["كَثِيرًۭا","many"],["مِّنْهُمْ","of them"],["فَـٰسِقُونَ","(are) defiantly disobedient"]]]});